window.__finlexDocLoaded(150,{"id":150,"articles":[{"id":3474,"no":"第一条","heading":"","text":"为了促进企业实现发展战略，优化治理结构、管理体制和运行机制，建立现代企业制度，根据《中华人民共和国公司法》等有关法律法规和《企业内部控制基本规范》，制定本指引。","seq":0},{"id":3475,"no":"第二条","heading":"","text":"本指引所称组织架构，是指企业按照国家有关法律法规、股东（大）会决议和企业章程，结合本企业实际，明确股东（大）会、董事会、监事会、经理层和企业内部各层级机构设置、职责权限、人员编制、工作程序和相关要求的制度安排。","seq":1},{"id":3476,"no":"第三条","heading":"","text":"企业至少应当关注组织架构设计与运行中的下列风险： （一）治理结构形同虚设，缺乏科学决策、良性运行机制和执行力，可能导致企业经营失败，难以实现发展战略。 （二）内部机构设计不科学，权责分配不合理，可能导致机构重叠、职能交叉或缺失、推诿扯皮，运行效率低下。 ### 第二章 组织架构的设计","seq":2},{"id":3477,"no":"第四条","heading":"","text":"企业应当根据国家有关法律法规的规定，明确董事会、监事会和经理层的职责权限、任职条件、议事规则和工作程序，确保决策、执行和监督相互分离，形成制衡。董事会对股东（大）会负责，依法行使企业的经营决策权。可按照股东（大）会的有关决议，设立战略、审计、提名、薪酬与考核等专门委员会，明确各专门委员会的职责权限、任职资格、议事规则和工作程序，为董事会科学决策提供支持。监事会对股东（大）会负责，监督企业董事、经理和其他高级管理人员依法履行职责。经理层对董事会负责，主持企业的生产经营管理工作。经理和其他高级管理人员的职责分工应当明确。董事会、监事会和经理层的产生程序应当合法合规，其人员构成、知识结构、能力素质应当满足履行职责的要求。","seq":3},{"id":3478,"no":"第五条","heading":"","text":"企业的重大决策、重大事项、重要人事任免及大额资金支付业务等，应当按照规定的权限和程序实行集体决策审批或者联签制度。任何个人不得单独进行决策或者擅自改变集体决策意见。重大决策、重大事项、重要人事任免及大额资金支付业务的具体标准由企业自行确定。","seq":4},{"id":3479,"no":"第六条","heading":"","text":"企业应当按照科学、精简、高效、透明、制衡的原则，综合考虑企业性质、发展战略、文化理念和管理要求等因素，合理设置内部职能机构，明确各机构的职责权限，避免职能交叉、缺失或权责过于集中，形成各司其职、各负其责、相互制约、相互协调的工作机制。","seq":5},{"id":3480,"no":"第七条","heading":"","text":"企业应当对各机构的职能进行科学合理的分解，确定具体岗位的名称、职责和工作要求等，明确各个岗位的权限和相互关系。企业在确定职权和岗位分工过程中，应当体现不相容职务相互分离的要求。不相容职务通常包括：可行性研究与决策审批；决策审批与执行；执行与监督检查等。","seq":6},{"id":3481,"no":"第八条","heading":"","text":"企业应当制定组织结构图、业务流程图、岗（职）位说明书和权限指引等内部管理制度或相关文件，使员工了解和掌握组织架构设计及权责分配情况，正确履行职责。 ### 第三章 组织架构的运行","seq":7},{"id":3482,"no":"第九条","heading":"","text":"企业应当根据组织架构的设计规范，对现有治理结构和内部机构设置进行全面梳理，确保本企业治理结构、内部机构设置和运行机制等符合现代企业制度要求。企业梳理治理结构，应当重点关注董事、监事、经理及其他高级管理人员的任职资格和履职情况，以及董事会、监事会和经理层的运行效果。治理结构存在问题的，应当采取有效措施加以改进。企业梳理内部机构设置，应当重点关注内部机构设置的合理性和运行的高效性等。内部机构设置和运行中存在职能交叉、缺失或运行效率低下的，应当及时解决。","seq":8},{"id":3483,"no":"第十条","heading":"","text":"企业拥有子公司的，应当建立科学的投资管控制度，通过合法有效的形式履行出资人职责、维护出资人权益，重点关注子公司特别是异地、境外子公司的发展战略、年度财务预决算、重大投融资、重大担保、大额资金使用、主要资产处置、重要人事任免、内部控制体系建设等重要事项。","seq":9},{"id":3484,"no":"第十一条","heading":"","text":"企业应当定期对组织架构设计与运行的效率和效果进行全面评估，发现组织架构设计与运行中存在缺陷的，应当进行优化调整。企业组织架构调整应当充分听取董事、监事、高级管理人员和其他员工的意见，按照规定的权限和程序进行决策审批。 ## 企业内部控制应用指引第2号——发展战略 ### 第一章 总则","seq":10},{"id":3485,"no":"第12条","heading":"第一条","text":"为了促进企业增强核心竞争力和可持续发展能力，根据有关法律法规和《企业内部控制基本规范》，制定本指引。","seq":11},{"id":3486,"no":"第13条","heading":"第二条","text":"本指引所称发展战略，是指企业在对现实状况和未来趋势进行综合分析和科学预测的基础上，制定并实施的长远发展目标与战略规划。","seq":12},{"id":3487,"no":"第14条","heading":"第三条","text":"企业制定与实施发展战略至少应当关注下列风险： （一）缺乏明确的发展战略或发展战略实施不到位，可能导致企业盲目发展，难以形成竞争优势，丧失发展机遇和动力。 （二）发展战略过于激进，脱离企业实际能力或偏离主业，可能导致企业过度扩张，甚至经营失败。 （三）发展战略因主观原因频繁变动，可能导致资源浪费，甚至危及企业的生存和持续发展。 ### 第二章 发展战略的制定","seq":13},{"id":3488,"no":"第15条","heading":"第四条","text":"企业应当在充分调查研究、科学分析预测和广泛征求意见的基础上制定发展目标。企业在制定发展目标过程中，应当综合考虑宏观经济政策、国内外市场需求变化、技术发展趋势、行业及竞争对手状况、可利用资源水平和自身优势与劣势等影响因素。","seq":14},{"id":3489,"no":"第16条","heading":"第五条","text":"企业应当根据发展目标制定战略规划。战略规划应当明确发展的阶段性和发展程度，确定每个发展阶段的具体目标、工作任务和实施路径。","seq":15},{"id":3490,"no":"第17条","heading":"第六条","text":"企业应当在董事会下设立战略委员会，或指定相关机构负责发展战略管理工作，履行相应职责。企业应当明确战略委员会的职责和议事规则，对战略委员会会议的召开程序、表决方式、提案审议、保密要求和会议记录等作出规定，确保议事过程规范透明、决策程序科学民主。战略委员会应当组织有关部门对发展目标和战略规划进行可行性研究和科学论证，形成发展战略建议方案；必要时，可借助中介机构和外部专家的力量为其履行职责提供专业咨询意见。战略委员会成员应当具有较强的综合素质和实践经验，其任职资格和选任程序应当符合有关法律法规和企业章程的规定。","seq":16},{"id":3491,"no":"第18条","heading":"第七条","text":"董事会应当严格审议战略委员会提交的发展战略方案，重点关注其全局性、长期性和可行性。董事会在审议方案中如果发现重大问题，应当责成战略委员会对方案作出调整。企业的发展战略方案经董事会审议通过后，报经股东（大）会批准实施。 ### 第三章 发展战略的实施","seq":17},{"id":3492,"no":"第19条","heading":"第八条","text":"企业应当根据发展战略，制定年度工作计划，编制全面预算，将年度目标分解、落实；同时完善发展战略管理制度，确保发展战略有效实施。","seq":18},{"id":3493,"no":"第20条","heading":"第九条","text":"企业应当重视发展战略的宣传工作，通过内部各层级会议和教育培训等有效方式，将发展战略及其分解落实情况传递到内部各管理层级和全体员工。","seq":19},{"id":3494,"no":"第21条","heading":"第十条","text":"战略委员会应当加强对发展战略实施情况的监控，定期收集和分析相关信息，对于明显偏离发展战略的情况，应当及时报告。","seq":20},{"id":3495,"no":"第22条","heading":"第十一条","text":"由于经济形势、产业政策、技术进步、行业状况以及不可抗力等因素发生重大变化，确需对发展战略作出调整的，应当按照规定权限和程序调整发展战略。 ## 企业内部控制应用指引第3号——人力资源 ### 第一章 总则","seq":21},{"id":3496,"no":"第23条","heading":"第一条","text":"为了促进企业加强人力资源建设，充分发挥人力资源对实现企业发展战略的重要作用，根据有关法律法规和《企业内部控制基本规范》，制定本指引。","seq":22},{"id":3497,"no":"第24条","heading":"第二条","text":"本指引所称人力资源，是指企业组织生产经营活动而录（任）用的各种人员，包括董事、监事、高级管理人员和全体员工。","seq":23},{"id":3498,"no":"第25条","heading":"第三条","text":"企业人力资源管理至少应当关注下列风险： （一）人力资源缺乏或过剩、结构不合理、开发机制不健全，可能导致企业发展战略难以实现。 （二）人力资源激励约束制度不合理、关键岗位人员管理不完善，可能导致人才流失、经营效率低下或关键技术、商业秘密和国家机密泄露。 （三）人力资源退出机制不当，可能导致法律诉讼或企业声誉受损。","seq":24},{"id":3499,"no":"第26条","heading":"第四条","text":"企业应当重视人力资源建设，根据发展战略，结合人力资源现状和未来需求预测，建立人力资源发展目标，制定人力资源总体规划和能力框架体系，优化人力资源整体布局，明确人力资源的引进、开发、使用、培养、考核、激励、退出等管理要求，实现人力资源的合理配置，全面提升企业核心竞争力。 ### 第二章 人力资源的引进与开发","seq":25},{"id":3500,"no":"第27条","heading":"第五条","text":"企业应当根据人力资源总体规划，结合生产经营实际需要，制定年度人力资源需求计划，完善人力资源引进制度，规范工作流程，按照计划、制度和程序组织人力资源引进工作。","seq":26},{"id":3501,"no":"第28条","heading":"第六条","text":"企业应当根据人力资源能力框架要求，明确各岗位的职责权限、任职条件和工作要求，遵循德才兼备、以德为先和公开、公平、公正的原则，通过公开招聘、竞争上岗等多种方式选聘优秀人才，重点关注选聘对象的价值取向和责任意识。企业选拔高级管理人员和聘用中层及以下员工，应当切实做到因事设岗、以岗选人，避免因人设事或设岗，确保选聘人员能够胜任岗位职责要求。企业选聘人员应当实行岗位回避制度。","seq":27},{"id":3502,"no":"第29条","heading":"第七条","text":"企业确定选聘人员后，应当依法签订劳动合同，建立劳动用工关系。企业对于在产品技术、市场、管理等方面掌握或涉及关键技术、知识产权、商业秘密或国家机密的工作岗位，应当与该岗位员工签订有关岗位保密协议，明确保密义务。","seq":28},{"id":3503,"no":"第30条","heading":"第八条","text":"企业应当建立选聘人员试用期和岗前培训制度，对试用人员进行严格考察，促进选聘员工全面了解岗位职责，掌握岗位基本技能，适应工作要求。试用期满考核合格后，方可正式上岗；试用期满考核不合格者，应当及时解除劳动关系。","seq":29},{"id":3504,"no":"第31条","heading":"第九条","text":"企业应当重视人力资源开发工作，建立员工培训长效机制，营造尊重知识、尊重人才和关心员工职业发展的文化氛围，加强后备人才队伍建设，促进全体员工的知识、技能持续更新，不断提升员工的服务效能。 ### 第三章 人力资源的使用与退出","seq":30},{"id":3505,"no":"第32条","heading":"第十条","text":"企业应当建立和完善人力资源的激励约束机制，设置科学的业绩考核指标体系，对各级管理人员和全体员工进行严格考核与评价，以此作为确定员工薪酬、职级调整和解除劳动合同等的重要依据，确保员工队伍处于持续优化状态。","seq":31},{"id":3506,"no":"第33条","heading":"第十一条","text":"企业应当制定与业绩考核挂钩的薪酬制度，切实做到薪酬安排与员工贡献相协调，体现效率优先，兼顾公平。","seq":32},{"id":3507,"no":"第十二条","heading":"","text":"企业应当制定各级管理人员和关键岗位员工定期轮岗制度，明确轮岗范围、轮岗周期、轮岗方式等，形成相关岗位员工的有序持续流动，全面提升员工素质。","seq":33},{"id":3508,"no":"第十三条","heading":"","text":"企业应当按照有关法律法规规定，结合企业实际，建立健全员工退出（辞职、解除劳动合同、退休等）机制，明确退出的条件和程序，确保员工退出机制得到有效实施。企业对考核不能胜任岗位要求的员工，应当及时暂停其工作，安排再培训，或调整工作岗位，安排转岗培训；仍不能满足岗位职责要求的，应当按照规定的权限和程序解除劳动合同。企业应当与退出员工依法约定保守关键技术、商业秘密、国家机密和竞业限制的期限，确保知识产权、商业秘密和国家机密的安全。企业关键岗位人员离职前，应当根据有关法律法规的规定进行工作交接或离任审计。","seq":34},{"id":3509,"no":"第十四条","heading":"","text":"企业应当定期对年度人力资源计划执行情况进行评估，总结人力资源管理经验，分析存在的主要缺陷和不足，完善人力资源政策，促进企业整体团队充满生机和活力。 ## 企业内部控制应用指引第4号——社会责任 ### 第一章 总则","seq":35},{"id":3510,"no":"第37条","heading":"第一条","text":"为了促进企业履行社会责任，实现企业与社会的协调发展，根据国家有关法律法规和《企业内部控制基本规范》，制定本指引。","seq":36},{"id":3511,"no":"第38条","heading":"第二条","text":"本指引所称社会责任，是指企业在经营发展过程中应当履行的社会职责和义务，主要包括安全生产、产品质量（含服务，下同）、环境保护、资源节约、促进就业、员工权益保护等。","seq":37},{"id":3512,"no":"第39条","heading":"第三条","text":"企业至少应当关注在履行社会责任方面的下列风险： （一）安全生产措施不到位，责任不落实，可能导致企业发生安全事故。 （二）产品质量低劣，侵害消费者利益，可能导致企业巨额赔偿、形象受损，甚至破产。 （三）环境保护投入不足，资源耗费大，造成环境污染或资源枯竭，可能导致企业巨额赔偿、缺乏发展后劲，甚至停业。 （四）促进就业和员工权益保护不够，可能导致员工积极性受挫，影响企业发展和社会稳定。","seq":38},{"id":3513,"no":"第40条","heading":"第四条","text":"企业应当重视履行社会责任，切实做到经济效益与社会效益、短期利益与长远利益、自身发展与社会发展相互协调，实现企业与员工、企业与社会、企业与环境的健康和谐发展。 ### 第二章 安全生产","seq":39},{"id":3514,"no":"第41条","heading":"第五条","text":"企业应当根据国家有关安全生产的规定，结合本企业实际情况，建立严格的安全生产管理体系、操作规范和应急预案，强化安全生产责任追究制度，切实做到安全生产。企业应当设立安全管理部门和安全监督机构，负责企业安全生产的日常监督管理工作。","seq":40},{"id":3515,"no":"第42条","heading":"第六条","text":"企业应当重视安全生产投入，在人力、物力、资金、技术等方面提供必要的保障，健全检查监督机制，确保各项安全措施落实到位，不得随意降低保障标准和要求。","seq":41},{"id":3516,"no":"第43条","heading":"第七条","text":"企业应当贯彻预防为主的原则，采用多种形式增强员工安全意识，重视岗位培训，对于特殊岗位实行资格认证制度。企业应当加强生产设备的经常性维护管理，及时排除安全隐患。","seq":42},{"id":3517,"no":"第44条","heading":"第八条","text":"企业如果发生生产安全事故，应当按照安全生产管理制度妥善处理，排除故障，减轻损失，追究责任。重大生产安全事故应当启动应急预案，同时按照国家有关规定及时报告，严禁迟报、谎报和瞒报。 ### 第三章 产品质量","seq":43},{"id":3518,"no":"第45条","heading":"第九条","text":"企业应当根据国家和行业相关产品质量的要求，从事生产经营活动，切实提高产品质量和服务水平，努力为社会提供优质安全健康的产品和服务，最大限度地满足消费者的需求，对社会和公众负责，接受社会监督，承担社会责任。","seq":44},{"id":3519,"no":"第46条","heading":"第十条","text":"企业应当规范生产流程，建立严格的产品质量控制和检验制度，严把质量关，禁止缺乏质量保障、危害人民生命健康的产品流向社会。","seq":45},{"id":3520,"no":"第47条","heading":"第十一条","text":"企业应当加强产品的售后服务。售后发现存在严重质量缺陷、隐患的产品，应当及时召回或采取其他有效措施，最大限度地降低或消除缺陷、隐患产品的社会危害。企业应当妥善处理消费者提出的投诉和建议，切实保护消费者权益。 ### 第四章 环境保护与资源节约","seq":46},{"id":3521,"no":"第48条","heading":"第十二条","text":"企业应当按照国家有关环境保护与资源节约的规定，结合本企业实际情况，建立环境保护与资源节约制度，认真落实节能减排责任，积极开发和使用节能产品，发展循环经济，降低污染物排放，提高资源综合利用效率。企业应当通过宣传教育等有效形式，不断提高员工的环境保护和资源节约意识。","seq":47},{"id":3522,"no":"第49条","heading":"第十三条","text":"企业应当重视生态保护，加大对环保工作的人力、物力、财力的投入和技术支持，不断改进工艺流程，降低能耗和污染物排放水平，实现清洁生产。企业应当加强对废气、废水、废渣的综合治理，建立废料回收和循环利用制度。","seq":48},{"id":3523,"no":"第50条","heading":"第十四条","text":"企业应当重视资源节约和资源保护，着力开发利用可再生资源，防止对不可再生资源进行掠夺性或毁灭性开发。企业应当重视国家产业结构相关政策，特别关注产业结构调整的发展要求，加快高新技术开发和传统产业改造，切实转变发展方式，实现低投入、低消耗、低排放和高效率。","seq":49},{"id":3524,"no":"第十五条","heading":"","text":"企业应当建立环境保护和资源节约的监控制度，定期开展监督检查，发现问题，及时采取措施予以纠正。污染物排放超过国家有关规定的，企业应当承担治理或相关法律责任。发生紧急、重大环境污染事件时，应当启动应急机制，及时报告和处理，并依法追究相关责任人的责任。 ### 第五章 促进就业与员工权益保护","seq":50},{"id":3525,"no":"第十六条","heading":"","text":"企业应当依法保护员工的合法权益，贯彻人力资源政策，保护员工依法享有劳动权利和履行劳动义务，保持工作岗位相对稳定，积极促进充分就业，切实履行社会责任。企业应当避免在正常经营情况下批量辞退员工，增加社会负担。","seq":51},{"id":3526,"no":"第十七条","heading":"","text":"企业应当与员工签订并履行劳动合同，遵循按劳分配、同工同酬的原则，建立科学的员工薪酬制度和激励机制，不得克扣或无故拖欠员工薪酬。企业应当建立高级管理人员与员工薪酬的正常增长机制，切实保持合理水平，维护社会公平。","seq":52},{"id":3527,"no":"第十八条","heading":"","text":"企业应当及时办理员工社会保险，足额缴纳社会保险费，保障员工依法享受社会保险待遇。企业应当按照有关规定做好健康管理工作，预防、控制和消除职业危害；按期对员工进行非职业性健康监护，对从事有职业危害作业的员工进行职业性健康监护。企业应当遵守法定的劳动时间和休息休假制度，确保员工的休息休假权利。","seq":53},{"id":3528,"no":"第十九条","heading":"","text":"企业应当加强职工代表大会和工会组织建设，维护员工合法权益，积极开展员工职业教育培训，创造平等发展机会。企业应当尊重员工人格，维护员工尊严，杜绝性别、民族、宗教、年龄等各种歧视，保障员工身心健康。","seq":54},{"id":3529,"no":"第二十条","heading":"","text":"企业应当按照产学研用相结合的社会需求，积极创建实习基地，大力支持社会有关方面培养、锻炼社会需要的应用型人才。","seq":55},{"id":3530,"no":"第二十一条","heading":"","text":"企业应当积极履行社会公益方面的责任和义务，关心帮助社会弱势群体，支持慈善事业。 ## 企业内部控制应用指引第5号——企业文化 ### 第一章 总则","seq":56},{"id":3531,"no":"第58条","heading":"第一条","text":"为了加强企业文化建设，发挥企业文化在企业发展中的重要作用，根据《企业内部控制基本规范》，制定本指引。","seq":57},{"id":3532,"no":"第59条","heading":"第二条","text":"本指引所称企业文化，是指企业在生产经营实践中逐步形成的、为整体团队所认同并遵守的价值观、经营理念和企业精神，以及在此基础上形成的行为规范的总称。","seq":58},{"id":3533,"no":"第60条","heading":"第三条","text":"加强企业文化建设至少应当关注下列风险： （一）缺乏积极向上的企业文化，可能导致员工丧失对企业的信心和认同感，企业缺乏凝聚力和竞争力。 （二）缺乏开拓创新、团队协作和风险意识，可能导致企业发展目标难以实现，影响可持续发展。 （三）缺乏诚实守信的经营理念，可能导致舞弊事件的发生，造成企业损失，影响企业信誉。 （四）忽视企业间的文化差异和理念冲突，可能导致并购重组失败。 ### 第二章 企业文化的建设","seq":59},{"id":3534,"no":"第61条","heading":"第四条","text":"企业应当采取切实有效的措施，积极培育具有自身特色的企业文化，引导和规范员工行为，打造以主业为核心的企业品牌，形成整体团队的向心力，促进企业长远发展。","seq":60},{"id":3535,"no":"第62条","heading":"第五条","text":"企业应当培育体现企业特色的发展愿景、积极向上的价值观、诚实守信的经营理念、履行社会责任和开拓创新的企业精神，以及团队协作和风险防范意识。企业应当重视并购重组后的企业文化建设，平等对待被并购方的员工，促进并购双方的文化融合。","seq":61},{"id":3536,"no":"第63条","heading":"第六条","text":"企业应当根据发展战略和实际情况，总结优良传统，挖掘文化底蕴，提炼核心价值，确定文化建设的目标和内容，形成企业文化规范，使其构成员工行为守则的重要组成部分。","seq":62},{"id":3537,"no":"第64条","heading":"第七条","text":"董事、监事、经理和其他高级管理人员应当在企业文化建设中发挥主导和垂范作用，以自身的优秀品格和脚踏实地的工作作风，带动影响整个团队，共同营造积极向上的企业文化环境。企业应当促进文化建设在内部各层级的有效沟通，加强企业文化的宣传贯彻，确保全体员工共同遵守。","seq":63},{"id":3538,"no":"第65条","heading":"第八条","text":"企业文化建设应当融入生产经营全过程，切实做到文化建设与发展战略的有机结合，增强员工的责任感和使命感，规范员工行为方式，使员工自身价值在企业发展中得到充分体现。企业应当加强对员工的文化教育和熏陶，全面提升员工的文化修养和内在素质。 ### 第三章 企业文化的评估","seq":64},{"id":3539,"no":"第66条","heading":"第九条","text":"企业应当建立企业文化评估制度，明确评估的内容、程序和方法，落实评估责任制，避免企业文化建设流于形式。","seq":65},{"id":3540,"no":"第67条","heading":"第十条","text":"企业文化评估，应当重点关注董事、监事、经理和其他高级管理人员在企业文化建设中的责任履行情况、全体员工对企业核心价值观的认同感、企业经营管理行为与企业文化的一致性、企业品牌的社会影响力、参与企业并购重组各方文化的融合度，以及员工对企业未来发展的信心。","seq":66},{"id":3541,"no":"第68条","heading":"第十一条","text":"企业应当重视企业文化的评估结果，巩固和发扬文化建设成果，针对评估过程中发现的问题，研究影响企业文化建设的不利因素，分析深层次的原因，及时采取措施加以改进。 ## 企业内部控制应用指引第6号——资金活动 ### 第一章 总则","seq":67},{"id":3542,"no":"第69条","heading":"第一条","text":"为了促进企业正常组织资金活动，防范和控制资金风险，保证资金安全，提高资金使用效益，根据有关法律法规和《企业内部控制基本规范》，制定本指引。","seq":68},{"id":3543,"no":"第70条","heading":"第二条","text":"本指引所称资金活动，是指企业筹资、投资和资金营运等活动的总称。","seq":69},{"id":3544,"no":"第71条","heading":"第三条","text":"企业资金活动至少应当关注下列风险： （一）筹资决策不当，引发资本结构不合理或无效融资，可能导致企业筹资成本过高或债务危机。 （二）投资决策失误，引发盲目扩张或丧失发展机遇，可能导致资金链断裂或资金使用效益低下。 （三）资金调度不合理、营运不畅，可能导致企业陷入财务困境或资金冗余。 （四）资金活动管控不严，可能导致资金被挪用、侵占、抽逃或遭受欺诈。","seq":70},{"id":3545,"no":"第72条","heading":"第四条","text":"企业应当根据自身发展战略，科学确定投融资目标和规划，完善严格的资金授权、批准、审验等相关管理制度，加强资金活动的集中归口管理，明确筹资、投资、营运等各环节的职责权限和岗位分离要求，定期或不定期检查和评价资金活动情况，落实责任追究制度，确保资金安全和有效运行。企业财会部门负责资金活动的日常管理，参与投融资方案等可行性研究。总会计师或分管会计工作的负责人应当参与投融资决策过程。企业有子公司的，应当采取合法有效措施，强化对子公司资金业务的统一监控。有条件的企业集团，应当探索财务公司、资金结算中心等资金集中管控模式。 ### 第二章 筹资","seq":71},{"id":3546,"no":"第73条","heading":"第五条","text":"企业应当根据筹资目标和规划，结合年度全面预算，拟订筹资方案，明确筹资用途、规模、结构和方式等相关内容，对筹资成本和潜在风险作出充分估计。境外筹资还应考虑所在地的政治、经济、法律、市场等因素。","seq":72},{"id":3547,"no":"第74条","heading":"第六条","text":"企业应当对筹资方案进行科学论证，不得依据未经论证的方案开展筹资活动。重大筹资方案应当形成可行性研究报告，全面反映风险评估情况。企业可以根据实际需要，聘请具有相应资质的专业机构进行可行性研究。","seq":73},{"id":3548,"no":"第75条","heading":"第七条","text":"企业应当对筹资方案进行严格审批，重点关注筹资用途的可行性和相应的偿债能力。重大筹资方案，应当按照规定的权限和程序实行集体决策或者联签制度。筹资方案需经有关部门批准的，应当履行相应的报批程序。筹资方案发生重大变更的，应当重新进行可行性研究并履行相应审批程序。","seq":74},{"id":3549,"no":"第76条","heading":"第八条","text":"企业应当根据批准的筹资方案，严格按照规定权限和程序筹集资金。银行借款或发行债券，应当重点关注利率风险、筹资成本、偿还能力以及流动性风险等；发行股票应当重点关注发行风险、市场风险、政策风险以及公司控制权风险等。企业通过银行借款方式筹资的，应当与有关金融机构进行洽谈，明确借款规模、利率、期限、担保、还款安排、相关的权利义务和违约责任等内容。双方达成一致意见后签署借款合同，据此办理相关借款业务。企业通过发行债券方式筹资的，应当合理选择债券种类，对还本付息方案作出系统安排，确保按期、足额偿还到期本金和利息。企业通过发行股票方式筹资的，应当依照《中华人民共和国证券法》等有关法律法规和证券监管部门的规定，优化企业组织架构，进行业务整合，并选择具备相应资质的中介机构协助企业做好相关工作，确保符合股票发行条件和要求。","seq":75},{"id":3550,"no":"第77条","heading":"第九条","text":"企业应当严格按照筹资方案确定的用途使用资金。筹资用于投资的，应当分别按照本指引第三章 和《企业内部控制应用指引第1 1号——工程项目》规定，防范和控制资金使用的风险。由于市场环境变化等确需改变资金用途的，应当履行相应的审批程序。严禁擅自改变资金用途。","seq":76},{"id":3551,"no":"第78条","heading":"第十条","text":"企业应当加强债务偿还和股利支付环节的管理，对偿还本息和支付股利等作出适当安排。企业应当按照筹资方案或合同约定的本金、利率、期限、汇率及币种，准确计算应付利息，与债权人核对无误后按期支付。企业应当选择合理的股利分配政策，兼顾投资者近期和长远利益，避免分配过度或不足。股利分配方案应当经过股东（大）会批准，并按规定履行披露义务。","seq":77},{"id":3552,"no":"第79条","heading":"第十一条","text":"企业应当加强筹资业务的会计系统控制，建立筹资业务的记录、凭证和账簿，按照国家统一会计准则制度，正确核算和监督资金筹集、本息偿还、股利支付等相关业务，妥善保管筹资合同或协议、收款凭证、入库凭证等资料，定期与资金提供方进行账务核对，确保筹资活动符合筹资方案的要求。 ### 第三章 投资","seq":78},{"id":3553,"no":"第80条","heading":"第十二条","text":"企业应当根据投资目标和规划，合理安排资金投放结构，科学确定投资项目，拟订投资方案，重点关注投资项目的收益和风险。企业选择投资项目应当突出主业，谨慎从事股票投资或衍生金融产品等高风险投资。境外投资还应考虑政治、经济、法律、市场等因素的影响。企业采用并购方式进行投资的，应当严格控制并购风险，重点关注并购对象的隐性债务、承诺事项、可持续发展能力、员工状况及其与本企业治理层及管理层的关联关系，合理确定支付对价，确保实现并购目标。","seq":79},{"id":3554,"no":"第81条","heading":"第十三条","text":"企业应当加强对投资方案的可行性研究，重点对投资目标、规模、方式、资金来源、风险与收益等作出客观评价。企业根据实际需要，可以委托具备相应资质的专业机构进行可行性研究，提供独立的可行性研究报告。","seq":80},{"id":3555,"no":"第82条","heading":"第十四条","text":"企业应当按照规定的权限和程序对投资项目进行决策审批，重点审查投资方案是否可行、投资项目是否符合国家产业政策及相关法律法规的规定，是否符合企业投资战略目标和规划、是否具有相应的资金能力、投入资金能否按时收回、预期收益能否实现，以及投资和并购风险是否可控等。重大投资项目，应当按照规定的权限和程序实行集体决策或者联签制度。投资方案需经有关管理部门批准的，应当履行相应的报批程序。投资方案发生重大变更的，应当重新进行可行性研究并履行相应审批程序。","seq":81},{"id":3556,"no":"第83条","heading":"第十五条","text":"企业应当根据批准的投资方案，与被投资方签订投资合同或协议，明确出资时间、金额、方式、双方权利义务和违约责任等内容，按规定的权限和程序审批后履行投资合同或协议。企业应当指定专门机构或人员对投资项目进行跟踪管理，及时收集被投资方经审计的财务报告等相关资料，定期组织投资效益分析，关注被投资方的财务状况、经营成果、现金流量以及投资合同履行情况，发现异常情况，应当及时报告并妥善处理。","seq":82},{"id":3557,"no":"第84条","heading":"第十六条","text":"企业应当加强对投资项目的会计系统控制，根据对被投资方的影响程度，合理确定投资会计政策，建立投资管理台账，详细记录投资对象、金额、持股比例、期限、收益等事项，妥善保管投资合同或协议、出资证明等资料。企业财会部门对于被投资方出现财务状况恶化、市价当期大幅下跌等情形的，应当根据国家统一的会计准则制度规定，合理计提减值准备、确认减值损失。","seq":83},{"id":3558,"no":"第85条","heading":"第十七条","text":"企业应当加强投资收回和处置环节的控制，对投资收回、转让、核销等决策和审批程序作出明确规定。企业应当重视投资到期本金的回收。转让投资应当由相关机构或人员合理确定转让价格，报授权批准部门批准，必要时可委托具有相应资质的专门机构进行评估。核销投资应当取得不能收回投资的法律文书和相关证明文件。企业对于到期无法收回的投资，应当建立责任追究制度。 ### 第四章 营运","seq":84},{"id":3559,"no":"第86条","heading":"第十八条","text":"企业应当加强资金营运全过程的管理，统筹协调内部各机构在生产经营过程中的资金需求，切实做好资金在采购、生产、销售等各环节的综合平衡，全面提升资金营运效率。","seq":85},{"id":3560,"no":"第87条","heading":"第十九条","text":"企业应当充分发挥全面预算管理在资金综合平衡中的作用，严格按照预算要求组织协调资金调度，确保资金及时收付，实现资金的合理占用和营运良性循环。企业应当严禁资金的体外循环，切实防范资金营运中的风险。","seq":86},{"id":3561,"no":"第88条","heading":"第二十条","text":"企业应当定期组织召开资金调度会或资金安全检查，对资金预算执行情况进行综合分析，发现异常情况，及时采取措施妥善处理，避免资金冗余或资金链断裂。企业在营运过程中出现临时性资金短缺的，可以通过短期融资等方式获取资金。资金出现短期闲置的，在保证安全性和流动性的前提下，可以通过购买国债等多种方式，提高资金效益。","seq":87},{"id":3562,"no":"第89条","heading":"第二十一条","text":"企业应当加强对营运资金的会计系统控制，严格规范资金的收支条件、程序和审批权限。企业在生产经营及其他业务活动中取得的资金收入应当及时入账，不得账外设账，严禁收款不入账、设立“小金库”。企业办理资金支付业务，应当明确支出款项的用途、金额、预算、限额、支付方式等内容，并附原始单据或相关证明，履行严格的授权审批程序后，方可安排资金支出。企业办理资金收付业务，应当遵守现金和银行存款管理的有关规定，不得由一人办理货币资金全过程业务，严禁将办理资金支付业务的相关印章和票据集中一人保管。 ## 企业内部控制应用指引第7号——采购业务 ### 第一章 总则","seq":88},{"id":3563,"no":"第90条","heading":"第一条","text":"为了促进企业合理采购，满足生产经营需要，规范采购行为，防范采购风险，根据有关法律法规和《企业内部控制基本规范》，制定本指引。","seq":89},{"id":3564,"no":"第91条","heading":"第二条","text":"本指引所称采购，是指购买物资（或接受劳务）及支付款项等相关活动。","seq":90},{"id":3565,"no":"第92条","heading":"第三条","text":"企业采购业务至少应当关注下列风险： （一）采购计划安排不合理，市场变化趋势预测不准确，造成库存短缺或积压，可能导致企业生产停滞或资源浪费。 （二）供应商选择不当，采购方式不合理，招投标或定价机制不科学，授权审批不规范，可能导致采购物资质次价高，出现舞弊或遭受欺诈。 （三）采购验收不规范，付款审核不严，可能导致采购物资、资金损失或信用受损。","seq":91},{"id":3566,"no":"第93条","heading":"第四条","text":"企业应当结合实际情况，全面梳理采购业务流程，完善采购业务相关管理制度，统筹安排采购计划，明确请购、审批、购买、验收、付款、采购后评估等环节的职责和审批权限，按照规定的审批权限和程序办理采购业务，建立价格监督机制，定期检查和评价采购过程中的薄弱环节，采取有效控制措施，确保物资采购满足企业生产经营需要。 ### 第二章 购买","seq":92},{"id":3567,"no":"第94条","heading":"第五条","text":"企业的采购业务应当集中，避免多头采购或分散采购，以提高采购业务效率，降低采购成本，堵塞管理漏洞。企业应当对办理采购业务的人员定期进行岗位轮换。重要和技术性较强的采购业务，应当组织相关专家进行论证，实行集体决策和审批。企业除小额零星物资或服务外，不得安排同一机构办理采购业务全过程。","seq":93},{"id":3568,"no":"第95条","heading":"第六条","text":"企业应当建立采购申请制度，依据购买物资或接受劳务的类型，确定归口管理部门，授予相应的请购权，明确相关部门或人员的职责权限及相应的请购和审批程序。企业可以根据实际需要设置专门的请购部门，对需求部门提出的采购需求进行审核，并进行归类汇总，统筹安排企业的采购计划。具有请购权的部门对于预算内采购项目，应当严格按照预算执行进度办理请购手续，并根据市场变化提出合理采购申请。对于超预算和预算外采购项目，应先履行预算调整程序，由具备相应审批权限的部门或人员审批后，再行办理请购手续。","seq":94},{"id":3569,"no":"第96条","heading":"第七条","text":"企业应当建立科学的供应商评估和准入制度，确定合格供应商清单，与选定的供应商签订质量保证协议，建立供应商管理信息系统，对供应商提供物资或劳务的质量、价格、交货及时性、供货条件及其资信、经营状况等进行实时管理和综合评价，根据评价结果对供应商进行合理选择和调整。企业可委托具有相应资质的中介机构对供应商进行资信调查。","seq":95},{"id":3570,"no":"第97条","heading":"第八条","text":"企业应当根据市场情况和采购计划合理选择采购方式。大宗采购应当采用招标方式，合理确定招投标的范围、标准、实施程序和评标规则；一般物资或劳务等的采购可以采用询价或定向采购的方式并签订合同协议；小额零星物资或劳务等的采购可以采用直接购买等方式。","seq":96},{"id":3571,"no":"第98条","heading":"第九条","text":"企业应当建立采购物资定价机制，采取协议采购、招标采购、谈判采购、询比价采购等多种方式合理确定采购价格，最大限度地减小市场变化对企业采购价格的影响。大宗采购等应当采用招投标方式确定采购价格，其他商品或劳务的采购，应当根据市场行情制定最高采购限价，并对最高采购限价适时调整。","seq":97},{"id":3572,"no":"第99条","heading":"第十条","text":"企业应当根据确定的供应商、采购方式、采购价格等情况拟订采购合同，准确描述合同条款，明确双方权利、义务和违约责任，按照规定权限签订采购合同。企业应当根据生产建设进度和采购物资特性，选择合理的运输工具和运输方式，办理运输、投保等事宜。","seq":98},{"id":3573,"no":"第100条","heading":"第十一条","text":"企业应当建立严格的采购验收制度，确定检验方式，由专门的验收机构或验收人员对采购项目的品种、规格、数量、质量等相关内容进行验收，出具验收证明。涉及大宗和新、特物资采购的，还应进行专业测试。验收过程中发现的异常情况，负责验收的机构或人员应当立即向企业有权管理的相关机构报告，相关机构应当查明原因并及时处理。","seq":99},{"id":3574,"no":"第101条","heading":"第十二条","text":"企业应当加强物资采购供应过程的管理，依据采购合同中确定的主要条款跟踪合同履行情况，对有可能影响生产或工程进度的异常情况，应出具书面报告并及时提出解决方案。企业应当做好采购业务各环节的记录，实行全过程的采购登记制度或信息化管理，确保采购过程的可追溯性。 ### 第三章 付款","seq":100},{"id":3575,"no":"第102条","heading":"第十三条","text":"企业应当加强采购付款的管理，完善付款流程，明确付款审核人的责任和权力，严格审核采购预算、合同、相关单据凭证、审批程序等相关内容，审核无误后按照合同规定及时办理付款。企业在付款过程中，应当严格审查采购发票的真实性、合法性和有效性。发现虚假发票的，应查明原因，及时报告处理。企业应当重视采购付款的过程控制和跟踪管理，发现异常情况的，应当拒绝付款，避免出现资金损失和信用受损。企业应当合理选择付款方式，并严格遵循合同规定，防范付款方式不当带来的法律风险，保证资金安全。","seq":101},{"id":3576,"no":"第103条","heading":"第十四条","text":"企业应当加强预付账款和定金的管理。涉及大额或长期的预付款项，应当定期进行追踪核查，综合分析预付账款的期限、占用款项的合理性、不可收回风险等情况，发现有疑问的预付款项，应当及时采取措施。","seq":102},{"id":3577,"no":"第104条","heading":"第十五条","text":"企业应当加强对购买、验收、付款业务的会计系统控制，详细记录供应商情况、请购申请、采购合同、采购通知、验收证明、入库凭证、商业票据、款项支付等情况，确保会计记录、采购记录与仓储记录核对一致。企业应当指定专人通过函证等方式，定期与供应商核对应付账款、应付票据、预付账款等往来款项。","seq":103},{"id":3578,"no":"第105条","heading":"第十六条","text":"企业应当建立退货管理制度，对退货条件、退货手续、货物出库、退货货款回收等作出明确规定，并在与供应商的合同中明确退货事宜，及时收回退货货款。涉及符合索赔条件的退货，应在索赔期内及时办理索赔。 ## 企业内部控制应用指引第8号——资产管理 ### 第一章 总则","seq":104},{"id":3579,"no":"第106条","heading":"第一条","text":"为了提高资产使用效能，保证资产安全，根据有关法律法规和《企业内部控制基本规范》，制定本指引。","seq":105},{"id":3580,"no":"第107条","heading":"第二条","text":"本指引所称资产，是指企业拥有或控制的存货、固定资产和无形资产。","seq":106},{"id":3581,"no":"第108条","heading":"第三条","text":"企业资产管理至少应当关注下列风险： （一）存货积压或短缺，可能导致流动资金占用过量、存货价值贬损或生产中断。 （二）固定资产更新改造不够、使用效能低下、维护不当、产能 过剩，可能导致企业缺乏竞争力、资产价值贬损、安全事故频发或资源浪费。 （三）无形资产缺乏核心技术、权属不清、技术落后、存在重大 技术安全隐患，可能导致企业法律纠纷、缺乏可持续发展能力。","seq":107},{"id":3582,"no":"第109条","heading":"第四条","text":"企业应当加强各项资产管理，全面梳理资产管理流程，及时发现资产管理中的薄弱环节，切实采取有效措施加以改进，并关注资产减值迹象，合理确认资产减值损失，不断提高企业资产管理水平。企业应当重视和加强各项资产的投保工作，采用招标等方式确定保险人，降低资产损失风险，防范资产投保舞弊。 ### 第二章 存货","seq":108},{"id":3583,"no":"第110条","heading":"第五条","text":"企业应当采用先进的存货管理技术和方法，规范存货管理流程，明确存货取得、验收入库、原料加工、仓储保管、领用发出、盘点处置等环节的管理要求，充分利用信息系统，强化会计、出入库等相关记录，确保存货管理全过程的风险得到有效控制。","seq":109},{"id":3584,"no":"第111条","heading":"第六条","text":"企业应当建立存货管理岗位责任制，明确内部相关部门和岗位的职责权限，切实做到不相容岗位相互分离、制约和监督。企业内部除存货管理、监督部门及仓储人员外，其他部门和人员接触存货，应当经过相关部门特别授权。","seq":110},{"id":3585,"no":"第112条","heading":"第七条","text":"企业应当重视存货验收工作，规范存货验收程序和方法，对入库存货的数量、质量、技术规格等方面进行查验，验收无误方可入库。外购存货的验收，应当重点关注合同、发票等原始单据与存货的数量、质量、规格等核对一致。涉及技术含量较高的货物，必要时可委托具有检验资质的机构或聘请外部专家协助验收。自制存货的验收，应当重点关注产品质量，通过检验合格的半成品、产成品才能办理入库手续，不合格品应及时查明原因、落实责任、报告处理。其他方式取得存货的验收，应当重点关注存货来源、质量状况、实际价值是否符合有关合同或协议的约定。","seq":111},{"id":3586,"no":"第113条","heading":"第八条","text":"企业应当建立存货保管制度，定期对存货进行检查，重点关注下列事项： （一）存货在不同仓库之间流动时应当办理出入库手续。 （二）应当按仓储物资所要求的储存条件贮存，并健全防火、防洪、防盗、防潮、防病虫害和防变质等管理规范。 （三）加强生产现场的材料、周转材料、半成品等物资的管理，防止浪费、被盗和流失。 （四）对代管、代销、暂存、受托加工的存货，应单独存放和记录，避免与本单位存货混淆。 （五）结合企业实际情况，加强存货的保险投保，保证存货安全，合理降低存货意外损失风险。","seq":112},{"id":3587,"no":"第114条","heading":"第九条","text":"企业应当明确存货发出和领用的审批权限，大批存货、贵重商品或危险品的发出应当实行特别授权。仓储部门应当根据经审批的销售（出库）通知单发出货物。","seq":113},{"id":3588,"no":"第115条","heading":"第十条","text":"企业仓储部门应当详细记录存货入库、出库及库存情况，做到存货记录与实际库存相符，并定期与财会部门、存货管理部门进行核对。","seq":114},{"id":3589,"no":"第116条","heading":"第十一条","text":"企业应当根据各种存货采购间隔期和当前库存，综合考虑企业生产经营计划、市场供求等因素，充分利用信息系统，合理确定存货采购日期和数量，确保存货处于最佳库存状态。","seq":115},{"id":3590,"no":"第117条","heading":"第十二条","text":"企业应当建立存货盘点清查制度，结合本企业实际情况确定盘点周期、盘点流程等相关内容，核查存货数量，及时发现存货减值迹象。企业至少应当于每年年度终了开展全面盘点清查，盘点清查结果应当形成书面报告。盘点清查中发现的存货盘盈、盘亏、毁损、闲置以及需要报废的存货，应当查明原因、落实并追究责任，按照规定权限批准后处置。 ### 第三章 固定资产","seq":116},{"id":3591,"no":"第118条","heading":"第十三条","text":"企业应当加强房屋建筑物、机器设备等各类固定资产的管理，重视固定资产维护和更新改造，不断提升固定资产的使用效能，积极促进固定资产处于良好运行状态。","seq":117},{"id":3592,"no":"第119条","heading":"第十四条","text":"企业应当制定固定资产目录，对每项固定资产进行编号，按照单项资产建立固定资产卡片，详细记录各项固定资产的来源、验收、使用地点、责任单位和责任人、运转、维修、改造、折旧、盘点等相关内容。企业应当严格执行固定资产日常维修和大修理计划，定期对固定资产进行维护保养，切实消除安全隐患。企业应当强化对生产线等关键设备运转的监控，严格操作流程，实行岗前培训和岗位许可制度，确保设备安全运转。","seq":118},{"id":3593,"no":"第120条","heading":"第十五条","text":"企业应当根据发展战略，充分利用国家有关自主创新政策，加大技改投入，不断促进固定资产技术升级，淘汰落后设备，切实做到保持本企业固定资产技术的先进性和企业发展的可持续性。","seq":119},{"id":3594,"no":"第121条","heading":"第十六条","text":"企业应当严格执行固定资产投保政策，对应投保的固定资产项目按规定程序进行审批，及时办理投保手续。","seq":120},{"id":3595,"no":"第122条","heading":"第十七条","text":"企业应当规范固定资产抵押管理，确定固定资产抵押程序和审批权限等。企业将固定资产用作抵押的，应由相关部门提出申请，经企业授权部门或人员批准后，由资产管理部门办理抵押手续。企业应当加强对接收的抵押资产的管理，编制专门的资产目录，合理评估抵押资产的价值。","seq":121},{"id":3596,"no":"第123条","heading":"第十八条","text":"企业应当建立固定资产清查制度，至少每年进行全面清查。对固定资产清查中发现的问题，应当查明原因，追究责任，妥善处理。企业应当加强固定资产处置的控制，关注固定资产处置中的关联交易和处置定价，防范资产流失。 ### 第四章 无形资产","seq":122},{"id":3597,"no":"第124条","heading":"第十九条","text":"企业应当加强对品牌、商标、专利、专有技术、土地使用权等无形资产的管理，分类制定无形资产管理办法，落实无形资产管理责任制，促进无形资产有效利用，充分发挥无形资产对提升企业核心竞争力的作用。","seq":123},{"id":3598,"no":"第125条","heading":"第二十条","text":"企业应当全面梳理外购、自行开发以及其他方式取得的各类无形资产的权属关系，加强无形资产权益保护，防范侵权行为和法律风险。无形资产具有保密性质的，应当采取严格保密措施，严防泄露商业秘密。企业购入或者以支付土地出让金等方式取得的土地使用权，应当取得土地使用权有效证明文件。","seq":124},{"id":3599,"no":"第126条","heading":"第二十一条","text":"企业应当定期对专利、专有技术等无形资产的先进性进行评估，淘汰落后技术，加大研发投入，促进技术更新换代，不断提升自主创新能力，努力做到核心技术处于同行业领先水平。","seq":125},{"id":3600,"no":"第二十二条","heading":"","text":"企业应当重视品牌建设，加强商誉管理，通过提供高质量产品和优质服务等多种方式，不断打造和培育主业品牌，切实维护和提升企业品牌的社会认可度。 ## 企业内部控制应用指引第9号——销售业务 ### 第一章 总则","seq":126},{"id":3601,"no":"第128条","heading":"第一条","text":"为了促进企业销售稳定增长，扩大市场份额，规范销售行为，防范销售风险，根据有关法律法规和《企业内部控制基本规范》，制定本指引。","seq":127},{"id":3602,"no":"第129条","heading":"第二条","text":"本指引所称销售，是指企业出售商品（或提供劳务）及收取款项等相关活动。","seq":128},{"id":3603,"no":"第130条","heading":"第三条","text":"企业销售业务至少应当关注下列风险： （一）销售政策和策略不当，市场预测不准确，销售渠道管理不当等，可能导致销售不畅、库存积压、经营难以为继。 （二）客户信用管理不到位，结算方式选择不当，账款回收不力等，可能导致销售款项不能收回或遭受欺诈。 （三）销售过程存在舞弊行为，可能导致企业利益受损。","seq":129},{"id":3604,"no":"第131条","heading":"第四条","text":"企业应当结合实际情况，全面梳理销售业务流程，完善销售业务相关管理制度，确定适当的销售政策和策略，明确销售、发货、收款等环节的职责和审批权限，按照规定的权限和程序办理销售业务，定期检查分析销售过程中的薄弱环节，采取有效控制措施，确保实现销售目标。 ### 第二章 销售","seq":130},{"id":3605,"no":"第132条","heading":"第五条","text":"企业应当加强市场调查，合理确定定价机制和信用方式，根据市场变化及时调整销售策略，灵活运用销售折扣、销售折让、信用销售、代销和广告宣传等多种策略和营销方式，促进销售目标实现，不断提高市场占有率。企业应当健全客户信用档案，关注重要客户资信变动情况，采取有效措施，防范信用风险。企业对于境外客户和新开发客户，应当建立严格的信用保证制度。","seq":131},{"id":3606,"no":"第133条","heading":"第六条","text":"企业在销售合同订立前，应当与客户进行业务洽谈、磋商或谈判，关注客户信用状况、销售定价、结算方式等相关内容。重大的销售业务谈判应当吸收财会、法律等专业人员参加，并形成完整的书面记录。销售合同应当明确双方的权利和义务，审批人员应当对销售合同草案进行严格审核。重要的销售合同，应当征询法律顾问或专家的意见。","seq":132},{"id":3607,"no":"第134条","heading":"第七条","text":"企业销售部门应当按照经批准的销售合同开具相关销售通知。发货和仓储部门应当对销售通知进行审核，严格按照所列项目组织发货，确保货物的安全发运。企业应当加强销售退回管理，分析销售退回原因，及时妥善处理。企业应当严格按照发票管理规定开具销售发票。严禁开具虚假发票。","seq":133},{"id":3608,"no":"第135条","heading":"第八条","text":"企业应当做好销售业务各环节的记录，填制相应的凭证，设置销售台账，实行全过程的销售登记制度。","seq":134},{"id":3609,"no":"第136条","heading":"第九条","text":"企业应当完善客户服务制度，加强客户服务和跟踪，提升客户满意度和忠诚度，不断改进产品质量和服务水平。 ### 第三章 收款","seq":135},{"id":3610,"no":"第137条","heading":"第十条","text":"企业应当完善应收款项管理制度，严格考核，实行奖惩。销售部门负责应收款项的催收，催收记录（包括往来函电）应妥善保存；财会部门负责办理资金结算并监督款项回收。","seq":136},{"id":3611,"no":"第138条","heading":"第十一条","text":"企业应当加强商业票据管理，明确商业票据的受理范围，严格审查商业票据的真实性和合法性，防止票据欺诈。企业应当关注商业票据的取得、贴现和背书，对已贴现但仍承担收款风险的票据以及逾期票据，应当进行追索监控和跟踪管理。","seq":137},{"id":3612,"no":"第139条","heading":"第十二条","text":"企业应当加强对销售、发货、收款业务的会计系统控制，详细记录销售客户、销售合同、销售通知、发运凭证、商业票据、款项收回等情况，确保会计记录、销售记录与仓储记录核对一致。企业应当指定专人通过函证等方式，定期与客户核对应收账款、应收票据、预收账款等往来款项。企业应当加强应收款项坏账的管理。应收款项全部或部分无法收回的，应当查明原因，明确责任，并严格履行审批程序，按照国家统一的会计准则制度进行处理。 ## 企业内部控制应用指引第10号——研究与开发 ### 第一章 总则","seq":138},{"id":3613,"no":"第140条","heading":"第一条","text":"为了促进企业自主创新，增强核心竞争力，有效控制研发风险，实现发展战略，根据有关法律法规和《企业内部控制基本规范》，制定本指引。","seq":139},{"id":3614,"no":"第141条","heading":"第二条","text":"本指引所称研究与开发，是指企业为获取新产品、新技术、新工艺等所开展的各种研发活动。","seq":140},{"id":3615,"no":"第142条","heading":"第三条","text":"企业开展研发活动至少应当关注下列风险： （一）研究项目未经科学论证或论证不充分，可能导致创新不足或资源浪费。 （二）研发人员配备不合理或研发过程管理不善，可能导致研发成本过高、舞弊或研发失败。 （三）研究成果转化应用不足、保护措施不力，可能导致企业利益受损。","seq":141},{"id":3616,"no":"第143条","heading":"第四条","text":"企业应当重视研发工作，根据发展战略，结合市场开拓和技术进步要求，科学制定研发计划，强化研发全过程管理，规范研发行为，促进研发成果的转化和有效利用，不断提升企业自主创新能力。 ### 第二章 立项与研究","seq":142},{"id":3617,"no":"第144条","heading":"第五条","text":"企业应当根据实际需要，结合研发计划，提出研究项目立项申请，开展可行性研究，编制可行性研究报告。企业可以组织独立于申请及立项审批之外的专业机构和人员进行评估论证，出具评估意见。","seq":143},{"id":3618,"no":"第145条","heading":"第六条","text":"研究项目应当按照规定的权限和程序进行审批，重大研究项目应当报经董事会或类似权力机构集体审议决策。审批过程中，应当重点关注研究项目促进企业发展的必要性、技术的先进性以及成果转化的可行性。","seq":144},{"id":3619,"no":"第146条","heading":"第七条","text":"企业应当加强对研究过程的管理，合理配备专业人员，严格落实岗位责任制，确保研究过程高效、可控。企业应当跟踪检查研究项目进展情况，评估各阶段研究成果，提供足够的经费支持，确保项目按期、保质完成，有效规避研究失败风险。企业研究项目委托外单位承担的，应当采用招标、协议等适当方式确定受托单位，签订外包合同，约定研究成果的产权归属、研究进度和质量标准等相关内容。","seq":145},{"id":3620,"no":"第147条","heading":"第八条","text":"企业与其他单位合作进行研究的，应当对合作单位进行尽职调查，签订书面合作研究合同，明确双方投资、分工、权利义务、研究成果产权归属等。","seq":146},{"id":3621,"no":"第148条","heading":"第九条","text":"企业应当建立和完善研究成果验收制度，组织专业人员对研究成果进行独立评审和验收。企业对于通过验收的研究成果，可以委托相关机构进行审查，确认是否申请专利或作为非专利技术、商业秘密等进行管理。企业对于需要申请专利的研究成果，应当及时办理有关专利申请手续。","seq":147},{"id":3622,"no":"第149条","heading":"第十条","text":"企业应当建立严格的核心研究人员管理制度，明确界定核心研究人员范围和名册清单，签署符合国家有关法律法规要求的保密协议。企业与核心研究人员签订劳动合同时，应当特别约定研究成果归属、离职条件、离职移交程序、离职后保密义务、离职后竞业限制年限及违约责任等内容。 ### 第三章 开发与保护","seq":148},{"id":3623,"no":"第150条","heading":"第十一条","text":"企业应当加强研究成果的开发，形成科研、生产、市场一体化的自主创新机制，促进研究成果转化。研究成果的开发应当分步推进，通过试生产充分验证产品性能，在获得市场认可后方可进行批量生产。","seq":149},{"id":3624,"no":"第151条","heading":"第十二条","text":"企业应当建立研究成果保护制度，加强对专利权、非专利技术、商业秘密及研发过程中形成的各类涉密图纸、程序、资料的管理，严格按照制度规定借阅和使用。禁止无关人员接触研究成果。","seq":150},{"id":3625,"no":"第152条","heading":"第十三条","text":"企业应当建立研发活动评估制度，加强对立项与研究、开发与保护等过程的全面评估，认真总结研发管理经验，分析存在的薄弱环节，完善相关制度和办法，不断改进和提升研发活动的管理水平。 ## 企业内部控制应用指引第11号——工程项目 ### 第一章 总则","seq":151},{"id":3626,"no":"第153条","heading":"第一条","text":"为了加强工程项目管理，提高工程质量，保证工程进度，控制工程成本，防范商业贿赂等舞弊行为，根据有关法律法规和《企业内部控制基本规范》，制定本指引。","seq":152},{"id":3627,"no":"第154条","heading":"第二条","text":"本指引所称工程项目，是指企业自行或者委托其他单位所进行的建造、安装工程。","seq":153},{"id":3628,"no":"第155条","heading":"第三条","text":"企业工程项目至少应当关注下列风险： （一）立项缺乏可行性研究或者可行性研究流于形式，决策不当，盲目上马，可能导致难以实现预期效益或项目失败。 （二）项目招标暗箱操作，存在商业贿赂，可能导致中标人实质上难以承担工程项目、中标价格失实及相关人员涉案。 （三）工程造价信息不对称，技术方案不落实，概预算脱离实际，可能导致项目投资失控。 （四）工程物资质次价高，工程监理不到位，项目资金不落实，可能导致工程质量低劣，进度延迟或中断。 （五）竣工验收不规范，最终把关不严，可能导致工程交付使用后存在重大隐患。","seq":154},{"id":3629,"no":"第156条","heading":"第四条","text":"企业应当建立和完善工程项目各项管理制度，全面梳理各个环节可能存在的风险点，规范工程立项、招标、造价、建设、验收等环节的工作流程，明确相关部门和岗位的职责权限，做到可行性研究与决策、概预算编制与审核、项目实施与价款支付、竣工决算与审计等不相容职务相互分离，强化工程建设全过程的监控，确保工程项目的质量、进度和资金安全。 ### 第二章 工程立项","seq":155},{"id":3630,"no":"第157条","heading":"第五条","text":"企业应当指定专门机构归口管理工程项目，根据发展战略和年度投资计划，提出项目建议书，开展可行性研究，编制可行性研究报告。项目建议书的主要内容包括：项目的必要性和依据、产品方案、拟建规模、建设地点、投资估算、资金筹措、项目进度安排、经济效果和社会效益的估计、环境影响的初步评价等。可行性研究报告的内容主要包括：项目概况，项目建设的必要性，市场预测，项目建设选址及建设条件论证，建设规模和建设内容，项目外部配套建设，环境保护，劳动保护与卫生防疫，消防、节能、节水，总投资及资金来源，经济、社会效益，项目建设周期及进度安排，招投标法规定的相关内容等。企业可以委托具有相应资质的专业机构开展可行性研究，并按照有关要求形成可行性研究报告。","seq":156},{"id":3631,"no":"第158条","heading":"第六条","text":"企业应当组织规划、工程、技术、财会、法律等部门的专家对项目建议书和可行性研究报告进行充分论证和评审，出具评审意见，作为项目决策的重要依据。在项目评审过程中，应当重点关注项目投资方案、投资规模、资金筹措、生产规模、投资效益、布局选址、技术、安全、设备、环境保护等方面，核实相关资料的来源和取得途径是否真实、可靠和完整。企业可以委托具有相应资质的专业机构对可行性研究报告进行评审，出具评审意见。从事项目可行性研究的专业机构不得再从事可行性研究报告的评审。","seq":157},{"id":3632,"no":"第159条","heading":"第七条","text":"企业应当按照规定的权限和程序对工程项目进行决策，决策过程应有完整的书面记录。重大工程项目的立项，应当报经董事会或类似权力机构集体审议批准。总会计师或分管会计工作的负责人应当参与项目决策。任何个人不得单独决策或者擅自改变集体决策意见。工程项目决策失误应当实行责任追究制度。","seq":158},{"id":3633,"no":"第160条","heading":"第八条","text":"企业应当在工程项目立项后、正式施工前，依法取得建设用地、城市规划、环境保护、安全、施工等方面的许可。 ### 第三章 工程招标","seq":159},{"id":3634,"no":"第161条","heading":"第九条","text":"企业的工程项目一般应当采用公开招标的方式，择优选择具有相应资质的承包单位和监理单位。在选择承包单位时，企业可以将工程的勘察、设计、施工、设备采购一并发包给一个项目总承包单位，也可以将其中的一项或者多项发包给一个工程总承包单位，但不得违背工程施工组织设计和招标设计计划，将应由一个承包单位完成的工程肢解为若干部分发包给几个承包单位。企业应当依照国家招投标法的规定，遵循公开、公正、平等竞争的原则，发布招标公告，提供载有招标工程的主要技术要求、主要合同条款、评标的标准和方法，以及开标、评标、定标的程序等内容的招标文件。企业可以根据项目特点决定是否编制标底。需要编制标底的，标底编制过程和标底应当严格保密。在确定中标人前，企业不得与投标人就投标价格、投标方案等实质性内容进行谈判。","seq":160},{"id":3635,"no":"第162条","heading":"第十条","text":"企业应当依法组织工程招标的开标、评标和定标，并接受有关部门的监督。","seq":161},{"id":3636,"no":"第163条","heading":"第十一条","text":"企业应当依法组建评标委员会。评标委员会由企业的代表和有关技术、经济方面的专家组成。评标委员会应当客观、公正地履行职务、遵守职业道德，对所提出的评审意见承担责任。企业应当采取必要的措施，保证评标在严格保密的情况下进行。评标委员会应当按照招标文件确定的标准和方法，对投标文件进行评审和比较，择优选择中标候选人。","seq":162},{"id":3637,"no":"第164条","heading":"第十二条","text":"评标委员会成员和参与评标的有关工作人员不得透露对投标文件的评审和比较、中标候选人的推荐情况以及与评标有关的其他情况，不得私下接触投标人，不得收受投标人的财物或者其他好处。","seq":163},{"id":3638,"no":"第165条","heading":"第十三条","text":"企业应当按照规定的权限和程序从中标候选人中确定中标人，及时向中标人发出中标通知书，在规定的期限内与中标人订立书面合同，明确双方的权利、义务和违约责任。企业和中标人不得再行订立背离合同实质性内容的其他协议。 ### 第四章 工程造价","seq":164},{"id":3639,"no":"第166条","heading":"第十四条","text":"企业应当加强工程造价管理，明确初步设计概算和施工图预算的编制方法，按照规定的权限和程序进行审核批准，确保概预算科学合理。企业可以委托具备相应资质的中介机构开展工程造价咨询工作。","seq":165},{"id":3640,"no":"第167条","heading":"第十五条","text":"企业应当向招标确定的设计单位提供详细的设计要求和基础资料，进行有效的技术、经济交流。初步设计应当在技术、经济交流的基础上，采用先进的设计管理实务技术，进行多方案比选。施工图设计深度及图纸交付进度应当符合项目要求，防止因设计深度不足、设计缺陷，造成施工组织、工期、工程质量、投资失控以及生产运行成本过高等问题。","seq":166},{"id":3641,"no":"第168条","heading":"第十六条","text":"企业应当建立设计变更管理制度。设计单位应当提供全面、及时的现场服务。因过失造成设计变更的，应当实行责任追究制度。","seq":167},{"id":3642,"no":"第169条","heading":"第十七条","text":"企业应当组织工程、技术、财会等部门的相关专业人员或委托具有相应资质的中介机构对编制的概预算进行审核，重点审查编制依据、项目内容、工程量的计算、定额套用等是否真实、完整和准确。工程项目概预算按照规定的权限和程序审核批准后执行。 ### 第五章 工程建设","seq":168},{"id":3643,"no":"第170条","heading":"第十八条","text":"企业应当加强对工程建设过程的监控，实行严格的概预算管理，切实做到及时备料，科学施工，保障资金，落实责任，确保工程项目达到设计要求。","seq":169},{"id":3644,"no":"第171条","heading":"第十九条","text":"按照合同约定，企业自行采购工程物资的，应当按照《企业内部控制应用指引第7号——采购业务》等相关指引的规定，组织工程物资采购、验收和付款；由承包单位采购工程物资的，企业应当加强监督，确保工程物资采购符合设计标准和合同要求。严禁不合格工程物资投入工程项目建设。重大设备和大宗材料的采购应当根据有关招标采购的规定执行。","seq":170},{"id":3645,"no":"第172条","heading":"第二十条","text":"企业应当实行严格的工程监理制度，委托经过招标确定的监理单位进行监理。工程监理单位应当依照国家法律法规及相关技术标准、设计文件和工程承包合同，对承包单位在施工质量、工期、进度、安全和资金使用等方面实施监督。工程监理人员应当具备良好的职业操守，客观公正地执行监理任务，发现工程施工不符合设计要求、施工技术标准和合同约定的，应当要求承包单位改正；发现工程设计不符合建筑工程质量标准或者合同约定的质量要求的，应当报告企业要求设计单位改正。未经工程监理人员签字，工程物资不得在工程上使用或者安装，不得进行下一道工序施工，不得拨付工程价款，不得进行竣工验收。","seq":171},{"id":3646,"no":"第173条","heading":"第二十一条","text":"企业财会部门应当加强与承包单位的沟通，准确掌握工程进度，根据合同约定，按照规定的审批权限和程序办理工程价款结算，不得无故拖欠。","seq":172},{"id":3647,"no":"第174条","heading":"第二十二条","text":"企业应当严格控制工程变更，确需变更的，应当按照规定的权限和程序进行审批。重大的项目变更应当按照项目决策和概预算控制的有关程序和要求重新履行审批手续。因工程变更等原因造成价款支付方式及金额发生变动的，应当提供完整的书面文件和其他相关资料，并对工程变更价款的支付进行严格审核。 ### 第六章 工程验收","seq":173},{"id":3648,"no":"第二十三条","heading":"","text":"企业收到承包单位的工程竣工报告后，应当及时编制竣工决算，开展竣工决算审计，组织设计、施工、监理等有关单位进行竣工验收。","seq":174},{"id":3649,"no":"第二十四条","heading":"","text":"企业应当组织审核竣工决算，重点审查决算依据是否完备，相关文件资料是否齐全，竣工清理是否完成，决算编制是否正确。企业应当加强竣工决算审计，未实施竣工决算审计的工程项目，不得办理竣工验收手续。","seq":175},{"id":3650,"no":"第二十五条","heading":"","text":"企业应当及时组织工程项目竣工验收。交付竣工验收的工程项目，应当符合规定的质量标准，有完整的工程技术经济资料，并具备国家规定的其他竣工条件。验收合格的工程项目，应当编制交付使用财产清单，及时办理交付使用手续。","seq":176},{"id":3651,"no":"第二十六条","heading":"","text":"企业应当按照国家有关档案管理的规定，及时收集、整理工程建设各环节的文件资料，建立完整的工程项目档案。","seq":177},{"id":3652,"no":"第二十七条","heading":"","text":"企业应当建立完工项目后评估制度，重点评价工程项目预期目标的实现情况和项目投资效益等，并以此作为绩效考核和责任追究的依据。 ## 企业内部控制应用指引第12号——担保业务 ### 第一章 总则","seq":178},{"id":3653,"no":"第180条","heading":"第一条","text":"为了加强企业担保业务管理，防范担保业务风险，根据《中华人民共和国担保法》等有关法律法规和《企业内部控制基本规范》，制定本指引。","seq":179},{"id":3654,"no":"第181条","heading":"第二条","text":"本指引所称担保，是指企业作为担保人按照公平、自愿、互利的原则与债权人约定，当债务人不履行债务时，依照法律规定和合同协议承担相应法律责任的行为。","seq":180},{"id":3655,"no":"第182条","heading":"第三条","text":"企业办理担保业务至少应当关注下列风险： （一）对担保申请人的资信状况调查不深，审批不严或越权审批，可能导致企业担保决策失误或遭受欺诈。 （二）对被担保人出现财务困难或经营陷入困境等状况监控不 力，应对措施不当，可能导致企业承担法律责任。 （三）担保过程中存在舞弊行为，可能导致经办审批等相关人员涉案或企业利益受损。","seq":181},{"id":3656,"no":"第183条","heading":"第四条","text":"企业应当依法制定和完善担保业务政策及相关管理制度，明确担保的对象、范围、方式、条件、程序、担保限额和禁止担保等事项，规范调查评估、审核批准、担保执行等环节的工作流程，按照政策、制度、流程办理担保业务，定期检查担保政策的执行情况及效果，切实防范担保业务风险。 ### 第二章 调查评估与审批","seq":182},{"id":3657,"no":"第184条","heading":"第五条","text":"企业应当指定相关部门负责办理担保业务，对担保申请人进行资信调查和风险评估，评估结果应出具书面报告。企业也可委托中介机构对担保业务进行资信调查和风险评估工作。企业在对担保申请人进行资信调查和风险评估时，应当重点关注以下事项： （一）担保业务是否符合国家法律法规和本企业担保政策等相关 要求。 （二）担保申请人的资信状况，一般包括：基本情况、资产质量、经营情况、偿债能力、盈利水平、信用程度、行业前景等。 （三）担保申请人用于担保和第三方担保的资产状况及其权利归 属。 （四）企业要求担保申请人提供反担保的，还应当对与反担保有关的资产状况进行评估。","seq":183},{"id":3658,"no":"第185条","heading":"第六条","text":"企业对担保申请人出现以下情形之一的，不得提供担保： （一）担保项目不符合国家法律法规和本企业担保政策的。 （二）已进入重组、托管、兼并或破产清算程序的。 （三）财务状况恶化、资不抵债、管理混乱、经营风险较大的。 （四）与其他企业存在较大经济纠纷，面临法律诉讼且可能承担较大赔偿责任的。 （五）与本企业已经发生过担保纠纷且仍未妥善解决的，或不能及时足额交纳担保费用的。","seq":184},{"id":3659,"no":"第186条","heading":"第七条","text":"企业应当建立担保授权和审批制度，规定担保业务的授权批准方式、权限、程序、责任和相关控制措施，在授权范围内进行审批，不得超越权限审批。重大担保业务，应当报经董事会或类似权力机构批准。经办人员应当在职责范围内，按照审批人员的批准意见办理担保业务。对于审批人超越权限审批的担保业务，经办人员应当拒绝办理。","seq":185},{"id":3660,"no":"第187条","heading":"第八条","text":"企业应当采取合法有效的措施加强对子公司担保业务的统一监控。企业内设机构未经授权不得办理担保业务。企业为关联方提供担保的，与关联方存在经济利益或近亲属关系的有关人员在评估与审批环节应当回避。对境外企业进行担保的，应当遵守外汇管理规定，并关注被担保人所在国家的政治、经济、法律等因素。","seq":186},{"id":3661,"no":"第188条","heading":"第九条","text":"被担保人要求变更担保事项的，企业应当重新履行调查评估与审批程序。 ### 第三章 执行与监控","seq":187},{"id":3662,"no":"第189条","heading":"第十条","text":"企业应当根据审核批准的担保业务订立担保合同。担保合同应明确被担保人的权利、义务、违约责任等相关内容，并要求被担保人定期提供财务报告与有关资料，及时通报担保事项的实施情况。担保申请人同时向多方申请担保的，企业应当在担保合同中明确约定本企业的担保份额和相应的责任。","seq":188},{"id":3663,"no":"第190条","heading":"第十一条","text":"企业担保经办部门应当加强担保合同的日常管理，定期监测被担保人的经营情况和财务状况，对被担保人进行跟踪和监督，了解担保项目的执行、资金的使用、贷款的归还、财务运行及风险等情况，确保担保合同有效履行。担保合同履行过程中，如果被担保人出现异常情况，应当及时报告，妥善处理。对于被担保人未按有法律效力的合同条款偿付债务或履行相关合同项下的义务的，企业应当按照担保合同履行义务，同时主张对被担保人的追索权。","seq":189},{"id":3664,"no":"第191条","heading":"第十二条","text":"企业应当加强对担保业务的会计系统控制，及时足额收取担保费用，建立担保事项台账，详细记录担保对象、金额、期限、用于抵押和质押的物品或权利以及其他有关事项。企业财会部门应当及时收集、分析被担保人担保期内经审计的财务报告等相关资料，持续关注被担保人的财务状况、经营成果、现金流量以及担保合同的履行情况，积极配合担保经办部门防范担保业务风险。对于被担保人出现财务状况恶化、资不抵债、破产清算等情形的，企业应当根据国家统一的会计准则制度规定，合理确认预计负债和损失。","seq":190},{"id":3665,"no":"第192条","heading":"第十三条","text":"企业应当加强对反担保财产的管理，妥善保管被担保人用于反担保的权利凭证，定期核实财产的存续状况和价值，发现问题及时处理，确保反担保财产安全完整。","seq":191},{"id":3666,"no":"第193条","heading":"第十四条","text":"企业应当建立担保业务责任追究制度，对在担保中出现重大决策失误、未履行集体审批程序或不按规定管理担保业务的部门及人员，应当严格追究相应的责任。","seq":192},{"id":3667,"no":"第194条","heading":"第十五条","text":"企业应当在担保合同到期时，全面清查用于担保的财产、权利凭证，按照合同约定及时终止担保关系。企业应当妥善保管担保合同、与担保合同相关的主合同、反担保函或反担保合同，以及抵押、质押的权利凭证和有关原始资料，切实做到担保业务档案完整无缺。 ## 企业内部控制应用指引第13号——业务外包 ### 第一章 总则","seq":193},{"id":3668,"no":"第195条","heading":"第一条","text":"为了加强业务外包管理，规范业务外包行为，防范业务外包风险，根据有关法律法规和《企业内部控制基本规范》，制定本指引。","seq":194},{"id":3669,"no":"第196条","heading":"第二条","text":"本指引所称业务外包，是指企业利用专业化分工优势，将日常经营中的部分业务委托给本企业以外的专业服务机构或其他经济组织（以下简称承包方）完成的经营行为。本指引不涉及工程项目外包。","seq":195},{"id":3670,"no":"第197条","heading":"第三条","text":"企业应当对外包业务实施分类管理，通常划分为重大外包业务和一般外包业务。重大外包业务是指对企业生产经营有重大影响的外包业务。外包业务通常包括：研发、资信调查、可行性研究、委托加工、物业管理、客户服务、IT服务等。","seq":196},{"id":3671,"no":"第198条","heading":"第四条","text":"企业的业务外包至少应当关注下列风险： （一）外包范围和价格确定不合理，承包方选择不当，可能导致企业遭受损失。 （二）业务外包监控不严、服务质量低劣，可能导致企业难以发挥业务外包的优势。 （三）业务外包存在商业贿赂等舞弊行为，可能导致企业相关人员涉案。","seq":197},{"id":3672,"no":"第199条","heading":"第五条","text":"企业应当建立和完善业务外包管理制度，规定业务外包的范围、方式、条件、程序和实施等相关内容，明确相关部门和岗位的职责权限，强化业务外包全过程的监控，防范外包风险，充分发挥业务外包的优势。企业应当权衡利弊，避免核心业务外包。 ### 第二章 承包方选择","seq":198},{"id":3673,"no":"第200条","heading":"第六条","text":"企业应当根据年度生产经营计划和业务外包管理制度，结合确定的业务外包范围，拟定实施方案，按照规定的权限和程序审核批准。总会计师或分管会计工作的负责人应当参与重大业务外包的决策。重大业务外包方案应当提交董事会或类似权力机构审批。","seq":199},{"id":3674,"no":"第201条","heading":"第七条","text":"企业应当按照批准的业务外包实施方案选择承包方。承包方至少应当具备下列条件： （一）承包方是依法成立和合法经营的专业服务机构或其他经济 组织，具有相应的经营范围和固定的办公场所。 （二）承包方应当具备相应的专业资质，其从业人员符合岗位要求和任职条件，并具有相应的专业技术资格。 （三）承包方的技术及经验水平符合本企业业务外包的要求。","seq":200},{"id":3675,"no":"第202条","heading":"第八条","text":"企业应当综合考虑内外部因素，合理确定外包价格，严格控制业务外包成本，切实做到符合成本效益原则。","seq":201},{"id":3676,"no":"第203条","heading":"第九条","text":"企业应当引入竞争机制，遵循公开、公平、公正的原则，采用适当方式，择优选择外包业务的承包方。采用招标方式选择承包方的，应当符合招投标法的相关规定。企业及相关人员在选择承包方的过程中，不得收受贿赂、回扣或者索取其他好处。承包方及其工作人员不得利用向企业及其工作人员行贿、提供回扣或者给予其他好处等不正当手段承揽业务。","seq":202},{"id":3677,"no":"第204条","heading":"第十条","text":"企业应当按照规定的权限和程序从候选承包方中确定最终承包方，并签订业务外包合同。业务外包合同内容主要包括：外包业务的内容和范围，双方权利和义务，服务和质量标准，保密事项，费用结算标准和违约责任等事项。","seq":203},{"id":3678,"no":"第205条","heading":"第十一条","text":"企业外包业务需要保密的，应当在业务外包合同或者另行签订的保密协议中明确规定承包方的保密义务和责任，要求承包方向其从业人员提示保密要求和应承担的责任。 ### 第三章 业务外包实施","seq":204},{"id":3679,"no":"第206条","heading":"第十二条","text":"企业应当加强业务外包实施的管理，严格按照业务外包制度、工作流程和相关要求，组织开展业务外包，并采取有效的控制措施，确保承包方严格履行业务外包合同。","seq":205},{"id":3680,"no":"第207条","heading":"第十三条","text":"企业应当做好与承包方的对接工作，加强与承包方的沟通与协调，及时搜集相关信息，发现和解决外包业务日常管理中存在的问题。对于重大业务外包，企业应当密切关注承包方的履约能力，建立相应的应急机制，避免业务外包失败造成本企业生产经营活动中断。","seq":206},{"id":3681,"no":"第208条","heading":"第十四条","text":"企业应当根据国家统一的会计准则制度，加强对外包业务的核算与监督，做好业务外包费用结算工作。","seq":207},{"id":3682,"no":"第209条","heading":"第十五条","text":"企业应当对承包方的履约能力进行持续评估，有确凿证据表明承包方存在重大违约行为，导致业务外包合同无法履行的，应当及时终止合同。承包方违约并造成企业损失的，企业应当按照合同对承包方进行索赔，并追究责任人责任。","seq":208},{"id":3683,"no":"第210条","heading":"第十六条","text":"业务外包合同执行完成后需要验收的，企业应当组织相关部门或人员对完成的业务外包合同进行验收，出具验收证明。验收过程中发现异常情况，应当立即报告，查明原因，及时处理。 ## 企业内部控制应用指引第14号——财务报告 ### 第一章 总则","seq":209},{"id":3684,"no":"第211条","heading":"第一条","text":"为了规范企业财务报告，保证财务报告的真实、完整，根据《中华人民共和国会计法》等有关法律法规和《企业内部控制基本规范》，制定本指引。","seq":210},{"id":3685,"no":"第212条","heading":"第二条","text":"本指引所称财务报告，是指反映企业某一特定日期财务状况和某一会计期间经营成果、现金流量的文件。","seq":211},{"id":3686,"no":"第213条","heading":"第三条","text":"企业编制、对外提供和分析利用财务报告，至少应当关注下列风险： （一）编制财务报告违反会计法律法规和国家统一的会计准则制 度，可能导致企业承担法律责任和声誉受损。 （二）提供虚假财务报告，误导财务报告使用者，造成决策失误，干扰市场秩序。 （三）不能有效利用财务报告，难以及时发现企业经营管理中存在的问题，可能导致企业财务和经营风险失控。","seq":212},{"id":3687,"no":"第214条","heading":"第四条","text":"企业应当严格执行会计法律法规和国家统一的会计准则制度，加强对财务报告编制、对外提供和分析利用全过程的管理，明确相关工作流程和要求，落实责任制，确保财务报告合法合规、真实完整和有效利用。总会计师或分管会计工作的负责人负责组织领导财务报告的编制、对外提供和分析利用等相关工作。企业负责人对财务报告的真实性、完整性负责。 ### 第二章 财务报告的编制","seq":213},{"id":3688,"no":"第215条","heading":"第五条","text":"企业编制财务报告，应当重点关注会计政策和会计估计，对财务报告产生重大影响的交易和事项的处理应当按照规定的权限和程序进行审批。企业在编制年度财务报告前，应当进行必要的资产清查、减值测试和债权债务核实。","seq":214},{"id":3689,"no":"第216条","heading":"第六条","text":"企业应当按照国家统一的会计准则制度规定，根据登记完整、核对无误的会计账簿记录和其他有关资料编制财务报告，做到内容完整、数字真实、计算准确，不得漏报或者随意进行取舍。","seq":215},{"id":3690,"no":"第217条","heading":"第七条","text":"企业财务报告列示的资产、负债、所有者权益金额应当真实可靠。各项资产计价方法不得随意变更，如有减值，应当合理计提减值准备，严禁虚增或虚减资产。各项负债应当反映企业的现时义务，不得提前、推迟或不确认负债，严禁虚增或虚减负债。所有者权益应当反映企业资产扣除负债后由所有者享有的剩余权益，由实收资本、资本公积、留存收益等构成。企业应当做好所有者权益保值增值工作，严禁虚假出资、抽逃出资、资本不实。","seq":216},{"id":3691,"no":"第218条","heading":"第八条","text":"企业财务报告应当如实列示当期收入、费用和利润。各项收入的确认应当遵循规定的标准，不得虚列或者隐瞒收入，推迟或提前确认收入。各项费用、成本的确认应当符合规定，不得随意改变费用、成本的确认标准或计量方法，虚列、多列、不列或者少列费用、成本。利润由收入减去费用后的净额、直接计入当期利润的利得和损失等构成。不得随意调整利润的计算、分配方法，编造虚假利润。","seq":217},{"id":3692,"no":"第219条","heading":"第九条","text":"企业财务报告列示的各种现金流量由经营活动、投资活动和筹资活动的现金流量构成，应当按照规定划清各类交易和事项的现金流量的界限。","seq":218},{"id":3693,"no":"第220条","heading":"第十条","text":"附注是财务报告的重要组成部分，对反映企业财务状况、经营成果、现金流量的报表中需要说明的事项，作出真实、完整、清晰的说明。企业应当按照国家统一的会计准则制度编制附注。","seq":219},{"id":3694,"no":"第221条","heading":"第十一条","text":"企业集团应当编制合并财务报表，明确合并财务报表的合并范围和合并方法，如实反映企业集团的财务状况、经营成果和现金流量。","seq":220},{"id":3695,"no":"第222条","heading":"第十二条","text":"企业编制财务报告，应当充分利用信息技术，提高工作效率和工作质量，减少或避免编制差错和人为调整因素。 ### 第三章 财务报告的对外提供","seq":221},{"id":3696,"no":"第223条","heading":"第十三条","text":"企业应当依照法律法规和国家统一的会计准则制度的规定，及时对外提供财务报告。","seq":222},{"id":3697,"no":"第224条","heading":"第十四条","text":"企业财务报告编制完成后，应当装订成册，加盖公章，由企业负责人、总会计师或分管会计工作的负责人、财会部门负责人签名并盖章。","seq":223},{"id":3698,"no":"第225条","heading":"第十五条","text":"财务报告须经注册会计师审计的，注册会计师及其所在的事务所出具的审计报告，应当随同财务报告一并提供。企业对外提供的财务报告应当及时整理归档，并按有关规定妥善保存。 ### 第四章 财务报告的分析利用","seq":224},{"id":3699,"no":"第226条","heading":"第十六条","text":"企业应当重视财务报告分析工作，定期召开财务分析会议，充分利用财务报告反映的综合信息，全面分析企业的经营管理状况和存在的问题，不断提高经营管理水平。企业财务分析会议应吸收有关部门负责人参加。总会计师或分管会计工作的负责人应当在财务分析和利用工作中发挥主导作用。","seq":225},{"id":3700,"no":"第227条","heading":"第十七条","text":"企业应当分析企业的资产分布、负债水平和所有者权益结构，通过资产负债率、流动比率、资产周转率等指标分析企业的偿债能力和营运能力；分析企业净资产的增减变化，了解和掌握企业规模和净资产的不断变化过程。","seq":226},{"id":3701,"no":"第228条","heading":"第十八条","text":"企业应当分析各项收入、费用的构成及其增减变动情况，通过净资产收益率、每股收益等指标，分析企业的盈利能力和发展能力，了解和掌握当期利润增减变化的原因和未来发展趋势。","seq":227},{"id":3702,"no":"第229条","heading":"第十九条","text":"企业应当分析经营活动、投资活动、筹资活动现金流量的运转情况，重点关注现金流量能否保证生产经营过程的正常运行，防止现金短缺或闲置。","seq":228},{"id":3703,"no":"第230条","heading":"第二十条","text":"企业定期的财务分析应当形成分析报告，构成内部报告的组成部分。财务分析报告结果应当及时传递给企业内部有关管理层级，充分发挥财务报告在企业生产经营管理中的重要作用。 ## 企业内部控制应用指引第15号——全面预算 ### 第一章 总则","seq":229},{"id":3704,"no":"第231条","heading":"第一条","text":"为了促进企业实现发展战略，发挥全面预算管理作用，根据有关法律法规和《企业内部控制基本规范》，制定本指引。","seq":230},{"id":3705,"no":"第232条","heading":"第二条","text":"本指引所称全面预算，是指企业对一定期间经营活动、投资活动、财务活动等作出的预算安排。","seq":231},{"id":3706,"no":"第233条","heading":"第三条","text":"企业实行全面预算管理，至少应当关注下列风险： （一）不编制预算或预算不健全，可能导致企业经营缺乏约束或盲目经营。 （二）预算目标不合理、编制不科学，可能导致企业资源浪费或发展战略难以实现。 （三）预算缺乏刚性、执行不力、考核不严，可能导致预算管理流于形式。","seq":232},{"id":3707,"no":"第234条","heading":"第四条","text":"企业应当加强全面预算工作的组织领导，明确预算管理体制以及各预算执行单位的职责权限、授权批准程序和工作协调机制。企业应当设立预算管理委员会履行全面预算管理职责，其成员由企业负责人及内部相关部门负责人组成。预算管理委员会主要负责拟定预算目标和预算政策，制定预算管理的具体措施和办法，组织编制、平衡预算草案，下达经批准的预算，协调解决预算编制和执行中的问题，考核预算执行情况，督促完成预算目标。预算管理委员会下设预算管理工作机构，由其履行日常管理职责。预算管理工作机构一般设在财会部门。总会计师或分管会计工作的负责人应当协助企业负责人负责企业全面预算管理工作的组织领导。 ### 第二章 预算编制","seq":233},{"id":3708,"no":"第235条","heading":"第五条","text":"企业应当建立和完善预算编制工作制度，明确编制依据、编制程序、编制方法等内容，确保预算编制依据合理、程序适当、方法科学，避免预算指标过高或过低。企业应当在预算年度开始前完成全面预算草案的编制工作。","seq":234},{"id":3709,"no":"第236条","heading":"第六条","text":"企业应当根据发展战略和年度生产经营计划，综合考虑预算期内经济政策、市场环境等因素，按照上下结合、分级编制、逐级汇总的程序，编制年度全面预算。企业可以选择或综合运用固定预算、弹性预算、滚动预算等方法编制预算。","seq":235},{"id":3710,"no":"第237条","heading":"第七条","text":"企业预算管理委员会应当对预算管理工作机构在综合平衡基础上提交的预算方案进行研究论证，从企业发展全局角度提出建议，形成全面预算草案，并提交董事会。","seq":236},{"id":3711,"no":"第238条","heading":"第八条","text":"企业董事会审核全面预算草案，应当重点关注预算科学性和可行性，确保全面预算与企业发展战略、年度生产经营计划相协调。企业全面预算应当按照相关法律法规及企业章程的规定报经审议批准。批准后，应当以文件形式下达执行。 ### 第三章 预算执行","seq":237},{"id":3712,"no":"第239条","heading":"第九条","text":"企业应当加强对预算执行的管理，明确预算指标分解方式、预算执行审批权限和要求、预算执行情况报告等，落实预算执行责任制，确保预算刚性，严格预算执行。","seq":238},{"id":3713,"no":"第240条","heading":"第十条","text":"企业全面预算一经批准下达，各预算执行单位应当认真组织实施，将预算指标层层分解，从横向和纵向落实到内部各部门、各环节和各岗位，形成全方位的预算执行责任体系。企业应当以年度预算作为组织、协调各项生产经营活动的基本依据，将年度预算细分为季度、月度预算，通过实施分期预算控制，实现年度预算目标。","seq":239},{"id":3714,"no":"第241条","heading":"第十一条","text":"企业应当根据全面预算管理要求，组织各项生产经营活动和投融资活动，严格预算执行和控制。企业应当加强资金收付业务的预算控制，及时组织资金收入，严格控制资金支付，调节资金收付平衡，防范支付风险。对于超预算或预算外的资金支付，应当实行严格的审批制度。企业办理采购与付款、销售与收款、成本费用、工程项目、对外投融资、研究与开发、信息系统、人力资源、安全环保、资产购置与维护等业务和事项，均应符合预算要求。涉及生产过程和成本费用的，还应执行相关计划、定额、定率标准。对于工程项目、对外投融资等重大预算项目，企业应当密切跟踪其实施进度和完成情况，实行严格监控。","seq":240},{"id":3715,"no":"第242条","heading":"第十二条","text":"企业预算管理工作机构应当加强与各预算执行单位的沟通，运用财务信息和其他相关资料监控预算执行情况，采用恰当方式及时向决策机构和各预算执行单位报告、反馈预算执行进度、执行差异及其对预算目标的影响，促进企业全面预算目标的实现。","seq":241},{"id":3716,"no":"第243条","heading":"第十三条","text":"企业预算管理工作机构和各预算执行单位应当建立预算执行情况分析制度，定期召开预算执行分析会议，通报预算执行情况，研究、解决预算执行中存在的问题，提出改进措施。企业分析预算执行情况，应当充分收集有关财务、业务、市场、技术、政策、法律等方面的信息资料，根据不同情况分别采用比率分析、比较分析、因素分析等方法，从定量与定性两个层面充分反映预算执行单位的现状、发展趋势及其存在的潜力。","seq":242},{"id":3717,"no":"第244条","heading":"第十四条","text":"企业批准下达的预算应当保持稳定，不得随意调整。由于市场环境、国家政策或不可抗力等客观因素，导致预算执行发生重大差异确需调整预算的，应当履行严格的审批程序。 ### 第四章 预算考核","seq":243},{"id":3718,"no":"第245条","heading":"第十五条","text":"企业应当建立严格的预算执行考核制度，对各预算执行单位和个人进行考核，切实做到有奖有惩、奖惩分明。","seq":244},{"id":3719,"no":"第246条","heading":"第十六条","text":"企业预算管理委员会应当定期组织预算执行情况考核，将各预算执行单位负责人签字上报的预算执行报告和已掌握的动态监控信息进行核对，确认各执行单位预算完成情况。必要时，实行预算执行情况内部审计制度。","seq":245},{"id":3720,"no":"第247条","heading":"第十七条","text":"企业预算执行情况考核工作，应当坚持公开、公平、公正的原则，考核过程及结果应有完整的记录。 ## 企业内部控制应用指引第16号——合同管理 ### 第一章 总则","seq":246},{"id":3721,"no":"第248条","heading":"第一条","text":"为了促进企业加强合同管理，维护企业合法权益，根据《中华人民共和国合同法》等有关法律法规和《企业内部控制基本规范》，制定本指引。","seq":247},{"id":3722,"no":"第249条","heading":"第二条","text":"本指引所称合同，是指企业与自然人、法人及其他组织等平等主体之间设立、变更、终止民事权利义务关系的协议。企业与职工签订的劳动合同，不适用本指引。","seq":248},{"id":3723,"no":"第250条","heading":"第三条","text":"企业合同管理至少应当关注下列风险： （一）未订立合同、未经授权对外订立合同、合同对方主体资格 未达要求、合同内容存在重大疏漏和欺诈，可能导致企业合法权益受到侵害。 （二）合同未全面履行或监控不当，可能导致企业诉讼失败、经济利益受损。 （三）合同纠纷处理不当，可能损害企业利益、信誉和形象。","seq":249},{"id":3724,"no":"第251条","heading":"第四条","text":"企业应当加强合同管理，确定合同归口管理部门，明确合同拟定、审批、执行等环节的程序和要求，定期检查和评价合同管理中的薄弱环节，采取相应控制措施，促进合同有效履行，切实维护企业的合法权益。 ### 第二章 合同的订立","seq":250},{"id":3725,"no":"第252条","heading":"第五条","text":"企业对外发生经济行为，除即时结清方式外，应当订立书面合同。合同订立前，应当充分了解合同对方的主体资格、信用状况等有关内容，确保对方当事人具备履约能力。对于影响重大、涉及较高专业技术或法律关系复杂的合同，应当组织法律、技术、财会等专业人员参与谈判，必要时可聘请外部专家参与相关工作。谈判过程中的重要事项和参与谈判人员的主要意见，应当予以记录并妥善保存。","seq":251},{"id":3726,"no":"第253条","heading":"第六条","text":"企业应当根据协商、谈判等的结果，拟订合同文本，按照自愿、公平原则，明确双方的权利义务和违约责任，做到条款内容完整，表述严谨准确，相关手续齐备，避免出现重大疏漏。合同文本一般由业务承办部门起草、法律部门审核。重大合同或法律关系复杂的特殊合同应当由法律部门参与起草。国家或行业有合同示范文本的，可以优先选用，但对涉及权利义务关系的条款应当进行认真审查，并根据实际情况进行适当修改。合同文本须报经国家有关主管部门审查或备案的，应当履行相应程序。","seq":252},{"id":3727,"no":"第254条","heading":"第七条","text":"企业应当对合同文本进行严格审核，重点关注合同的主体、内容和形式是否合法，合同内容是否符合企业的经济利益，对方当事人是否具有履约能力，合同权利和义务、违约责任和争议解决条款是否明确等。企业对影响重大或法律关系复杂的合同文本，应当组织内部相关部门进行审核。相关部门提出不同意见的，应当认真分析研究，慎重对待，并准确无误地加以记录；必要时应对合同条款作出修改。内部相关部门应当认真履行职责。","seq":253},{"id":3728,"no":"第255条","heading":"第八条","text":"企业应当按照规定的权限和程序与对方当事人签署合同。正式对外订立的合同，应当由企业法定代表人或由其授权的代理人签名或加盖有关印章。授权签署合同的，应当签署授权委托书。属于上级管理权限的合同，下级单位不得签署。下级单位认为确有需要签署涉及上级管理权限的合同，应当提出申请，并经上级合同管理机构批准后办理。上级单位应当加强对下级单位合同订立、履行情况的监督检查。","seq":254},{"id":3729,"no":"第256条","heading":"第九条","text":"企业应当建立合同专用章保管制度。合同经编号、审批及企业法定代表人或由其授权的代理人签署后，方可加盖合同专用章。","seq":255},{"id":3730,"no":"第257条","heading":"第十条","text":"企业应当加强合同信息安全保密工作，未经批准，不得以任何形式泄露合同订立与履行过程中涉及的商业秘密或国家机密。 ### 第三章 合同的履行","seq":256},{"id":3731,"no":"第258条","heading":"第十一条","text":"企业应当遵循诚实信用原则严格履行合同，对合同履行实施有效监控，强化对合同履行情况及效果的检查、分析和验收，确保合同全面有效履行。合同生效后，企业就质量、价款、履行地点等内容与合同对方没有约定或者约定不明确的，可以协议补充；不能达成补充协议的，按照国家相关法律法规、合同有关条款或者交易习惯确定。","seq":257},{"id":3732,"no":"第259条","heading":"第十二条","text":"在合同履行过程中发现有显失公平、条款有误或对方有欺诈行为等情形，或因政策调整、市场变化等客观因素，已经或可能导致企业利益受损，应当按规定程序及时报告，并经双方协商一致，按照规定权限和程序办理合同变更或解除事宜。","seq":258},{"id":3733,"no":"第260条","heading":"第十三条","text":"企业应当加强合同纠纷管理，在履行合同过程中发生纠纷的，应当依据国家相关法律法规，在规定时效内与对方当事人协商并按规定权限和程序及时报告。合同纠纷经协商一致的，双方应当签订书面协议。合同纠纷经协商无法解决的，应当根据合同约定选择仲裁或诉讼方式解决。企业内部授权处理合同纠纷的，应当签署授权委托书。纠纷处理过程中，未经授权批准，相关经办人员不得向对方当事人作出实质性答复或承诺。","seq":259},{"id":3734,"no":"第261条","heading":"第十四条","text":"企业财会部门应当根据合同条款审核后办理结算业务。未按合同条款履约的，或应签订书面合同而未签订的，财会部门有权拒绝付款，并及时向企业有关负责人报告。","seq":260},{"id":3735,"no":"第262条","heading":"第十五条","text":"合同管理部门应当加强合同登记管理，充分利用信息化手段，定期对合同进行统计、分类和归档，详细登记合同的订立、履行和变更等情况，实行合同的全过程封闭管理。","seq":261},{"id":3736,"no":"第263条","heading":"第十六条","text":"企业应当建立合同履行情况评估制度，至少于每年年末对合同履行的总体情况和重大合同履行的具体情况进行分析评估，对分析评估中发现合同履行中存在的不足，应当及时加以改进。企业应当健全合同管理考核与责任追究制度。对合同订立、履行过程中出现的违法违规行为，应当追究有关机构或人员的责任。 ## 企业内部控制应用指引第17号——内部信息传递 ### 第一章 总则","seq":262},{"id":3737,"no":"第264条","heading":"第一条","text":"为了促进企业生产经营管理信息在内部各管理层级之间的有效沟通和充分利用，根据《企业内部控制基本规范》，制定本指引。","seq":263},{"id":3738,"no":"第265条","heading":"第二条","text":"本指引所称内部信息传递，是指企业内部各管理层级之间通过内部报告形式传递生产经营管理信息的过程。","seq":264},{"id":3739,"no":"第266条","heading":"第三条","text":"企业内部信息传递至少应当关注下列风险： （一）内部报告系统缺失、功能不健全、内容不完整，可能影响生产经营有序运行。 （二）内部信息传递不通畅、不及时，可能导致决策失误、相关政策措施难以落实。 （三）内部信息传递中泄露商业秘密，可能削弱企业核心竞争力。","seq":265},{"id":3740,"no":"第267条","heading":"第四条","text":"企业应当加强内部报告管理，全面梳理内部信息传递过程中的薄弱环节，建立科学的内部信息传递机制，明确内部信息传递的内容、保密要求及密级分类、传递方式、传递范围以及各管理层级的职责权限等，促进内部报告的有效利用，充分发挥内部报告的作用。 ### 第二章 内部报告的形成","seq":266},{"id":3741,"no":"第268条","heading":"第五条","text":"企业应当根据发展战略、风险控制和业绩考核要求，科学规范不同级次内部报告的指标体系，采用经营快报等多种形式，全面反映与企业生产经营管理相关的各种内外部信息。内部报告指标体系的设计应当与全面预算管理相结合，并随着环境和业务的变化不断进行修订和完善。设计内部报告指标体系时，应当关注企业成本费用预算的执行情况。内部报告应当简洁明了、通俗易懂、传递及时，便于企业各管理层级和全体员工掌握相关信息，正确履行职责。","seq":267},{"id":3742,"no":"第269条","heading":"第六条","text":"企业应当制定严密的内部报告流程，充分利用信息技术，强化内部报告信息集成和共享，将内部报告纳入企业统一信息平台，构建科学的内部报告网络体系。企业内部各管理层级均应当指定专人负责内部报告工作，重要信息应及时上报，并可以直接报告高级管理人员。企业应当建立内部报告审核制度，确保内部报告信息质量。","seq":268},{"id":3743,"no":"第270条","heading":"第七条","text":"企业应当关注市场环境、政策变化等外部信息对企业生产经营管理的影响，广泛收集、分析、整理外部信息，并通过内部报告传递到企业内部相关管理层级，以便采取应对策略。","seq":269},{"id":3744,"no":"第271条","heading":"第八条","text":"企业应当拓宽内部报告渠道，通过落实奖励措施等多种有效方式，广泛收集合理化建议。企业应当重视和加强反舞弊机制建设,通过设立员工信箱、投诉热线等方式，鼓励员工及企业利益相关方举报和投诉企业内部的违法违规、舞弊和其他有损企业形象的行为。 ### 第三章 内部报告的使用","seq":270},{"id":3745,"no":"第272条","heading":"第九条","text":"企业各级管理人员应当充分利用内部报告管理和指导企业的生产经营活动，及时反映全面预算执行情况，协调企业内部相关部门和各单位的运营进度，严格绩效考核和责任追究，确保企业实现发展目标。","seq":271},{"id":3746,"no":"第273条","heading":"第十条","text":"企业应当有效利用内部报告进行风险评估，准确识别和系统分析企业生产经营活动中的内外部风险，确定风险应对策略，实现对风险的有效控制。企业对于内部报告反映出的问题应当及时解决；涉及突出问题和重大风险的，应当启动应急预案。","seq":272},{"id":3747,"no":"第274条","heading":"第十一条","text":"企业应当制定严格的内部报告保密制度，明确保密内容、保密措施、密级程度和传递范围，防止泄露商业秘密。","seq":273},{"id":3748,"no":"第275条","heading":"第十二条","text":"企业应当建立内部报告的评估制度，定期对内部报告的形成和使用进行全面评估，重点关注内部报告的及时性、安全性和有效性。 ## 企业内部控制应用指引第18号——信息系统 ### 第一章 总则","seq":274},{"id":3749,"no":"第276条","heading":"第一条","text":"为了促进企业有效实施内部控制，提高企业现代化管理水平，减少人为因素，根据有关法律法规和《企业内部控制基本规范》，制定本指引。","seq":275},{"id":3750,"no":"第277条","heading":"第二条","text":"本指引所称信息系统，是指企业利用计算机和通信技术，对内部控制进行集成、转化和提升所形成的信息化管理平台。","seq":276},{"id":3751,"no":"第278条","heading":"第三条","text":"企业利用信息系统实施内部控制至少应当关注下列风险： （一）信息系统缺乏或规划不合理，可能造成信息孤岛或重复建设，导致企业经营管理效率低下。 （二）系统开发不符合内部控制要求，授权管理不当，可能导致无法利用信息技术实施有效控制。 （三）系统运行维护和安全措施不到位，可能导致信息泄漏或毁损，系统无法正常运行。","seq":277},{"id":3752,"no":"第279条","heading":"第四条","text":"企业应当重视信息系统在内部控制中的作用，根据内部控制要求，结合组织架构、业务范围、地域分布、技术能力等因素，制定信息系统建设整体规划，加大投入力度，有序组织信息系统开发、运行与维护，优化管理流程，防范经营风险，全面提升企业现代化管理水平。企业应当指定专门机构对信息系统建设实施归口管理，明确相关单位的职责权限，建立有效工作机制。企业可委托专业机构从事信息系统的开发、运行和维护工作。企业负责人对信息系统建设工作负责。 ### 第二章 信息系统的开发","seq":278},{"id":3753,"no":"第280条","heading":"第五条","text":"企业应当根据信息系统建设整体规划提出项目建设方案，明确建设目标、人员配备、职责分工、经费保障和进度安排等相关内容，按照规定的权限和程序审批后实施。企业信息系统归口管理部门应当组织内部各单位提出开发需求和关键控制点，规范开发流程，明确系统设计、编程、安装调试、验收、上线等全过程的管理要求，严格按照建设方案、开发流程和相关要求组织开发工作。企业开发信息系统，可以采取自行开发、外购调试、业务外包等方式。选定外购调试或业务外包方式的，应当采用公开招标等形式择优确定供应商或开发单位。","seq":279},{"id":3754,"no":"第281条","heading":"第六条","text":"企业开发信息系统，应当将生产经营管理业务流程、关键控制点和处理规则嵌入系统程序，实现手工环境下难以实现的控制功能。企业在系统开发过程中，应当按照不同业务的控制要求，通过信息系统中的权限管理功能控制用户的操作权限，避免将不相容职责的处理权限授予同一用户。企业应当针对不同数据的输入方式，考虑对进入系统数据的检查和校验功能。对于必需的后台操作，应当加强管理，建立规范的流程制度，对操作情况进行监控或者审计。企业应当在信息系统中设置操作日志功能，确保操作的可审计性。对异常的或者违背内部控制要求的交易和数据，应当设计由系统自动报告并设置跟踪处理机制。","seq":280},{"id":3755,"no":"第282条","heading":"第七条","text":"企业信息系统归口管理部门应当加强信息系统开发全过程的跟踪管理，组织开发单位与内部各单位的日常沟通和协调，督促开发单位按照建设方案、计划进度和质量要求完成编程工作，对配备的硬件设备和系统软件进行检查验收，组织系统上线运行等。","seq":281},{"id":3756,"no":"第283条","heading":"第八条","text":"企业应当组织独立于开发单位的专业机构对开发完成的信息系统进行验收测试，确保在功能、性能、控制要求和安全性等方面符合开发需求。","seq":282},{"id":3757,"no":"第284条","heading":"第九条","text":"企业应当切实做好信息系统上线的各项准备工作，培训业务操作和系统管理人员，制定科学的上线计划和新旧系统转换方案，考虑应急预案，确保新旧系统顺利切换和平稳衔接。系统上线涉及数据迁移的，还应制定详细的数据迁移计划。 ### 第三章 信息系统的运行与维护","seq":283},{"id":3758,"no":"第285条","heading":"第十条","text":"企业应当加强信息系统运行与维护的管理，制定信息系统工作程序、信息管理制度以及各模块子系统的具体操作规范，及时跟踪、发现和解决系统运行中存在的问题，确保信息系统按照规定的程序、制度和操作规范持续稳定运行。企业应当建立信息系统变更管理流程，信息系统变更应当严格遵照管理流程进行操作。信息系统操作人员不得擅自进行系统软件的删除、修改等操作；不得擅自升级、改变系统软件版本；不得擅自改变软件系统环境配置。","seq":284},{"id":3759,"no":"第286条","heading":"第十一条","text":"企业应当根据业务性质、重要性程度、涉密情况等确定信息系统的安全等级，建立不同等级信息的授权使用制度，采用相应技术手段保证信息系统运行安全有序。企业应当建立信息系统安全保密和泄密责任追究制度。委托专业机构进行系统运行与维护管理的，应当审查该机构的资质，并与其签订服务合同和保密协议。企业应当采取安装安全软件等措施防范信息系统受到病毒等恶意软件的感染和破坏。","seq":285},{"id":3760,"no":"第287条","heading":"第十二条","text":"企业应当建立用户管理制度，加强对重要业务系统的访问权限管理，定期审阅系统账号，避免授权不当或存在非授权账号，禁止不相容职务用户账号的交叉操作。","seq":286},{"id":3761,"no":"第288条","heading":"第十三条","text":"企业应当综合利用防火墙、路由器等网络设备，漏洞扫描、入侵检测等软件技术以及远程访问安全策略等手段，加强网络安全，防范来自网络的攻击和非法侵入。企业对于通过网络传输的涉密或关键数据，应当采取加密措施，确保信息传递的保密性、准确性和完整性。","seq":287},{"id":3762,"no":"第289条","heading":"第十四条","text":"企业应当建立系统数据定期备份制度，明确备份范围、频度、方法、责任人、存放地点、有效性检查等内容。","seq":288},{"id":3763,"no":"第290条","heading":"第十五条","text":"企业应当加强服务器等关键信息设备的管理，建立良好的物理环境，指定专人负责检查，及时处理异常情况。未经授权，任何人不得接触关键信息设备。","seq":289}]});
